(32, 2, 'Chợ Mạch Tràng', 'cho-mach-trang-oefHf', 8, 4, NULL, '[{\"id\":1,\"tag\":\"🛡️ KIỂM ĐỊNH ATTP\",\"time\":\"Mới cập nhật\",\"title\":\"100% sạp đạt chuẩn ATTP Tháng 7\\/2026\",\"content\":\"Đoàn kiểm tra liên ngành đã nghiệm thu chất lượng nguồn gốc nông sản & vệ sinh quầy hàng.\",\"color\":\"#10B981\"},{\"id\":2,\"tag\":\"🧼 VỆ SINH ĐỊNH KỲ\",\"time\":\"18h00 Chủ Nhật\",\"title\":\"Lịch phun khử khuẩn toàn chợ\",\"content\":\"BQL tiến hành dọn vệ sinh tổng thể & phun tiêu độc khử khuẩn định kỳ vào cuối tuần.\",\"color\":\"#0ea5e9\"},{\"id\":3,\"tag\":\"🎪 SỰ KIỆN NÔNG SẢN\",\"time\":\"Sáng Thứ 7\",\"title\":\"Phiên Chợ Nông Sản Sạch Đông Anh\",\"content\":\"Quy tụ các hợp tác xã nông sản sạch, rau VietGAP & OCOP giá ưu đãi tại Khối B.\",\"color\":\"#f59e0b\"}]', '4V48+XPM, Cổ Loa, Đông Anh, Hà Nội, Việt Nam', NULL, NULL, 21.107475, 105.866782, '30.000đ - 100.000đ', 'https://media.xadonganh.com/eateries/1784892470_aEoYQMry.png', 0, 5.00, 'active', NULL, '2026-06-01 08:58:13', '2026-07-27 08:51:42'),
