(32, 150, 'Câu lạc bộ Kỹ năng sống & STEM', 'Chương trình phát triển toàn diện kỹ năng mềm, thuyết trình trước đám đông kết hợp lắp ráp robot và lập trình STEM cơ bản.', 'https://images.unsplash.com/photo-1564981797816-1043664bf78d?auto=format&fit=crop&w=800&q=80', NULL, 0, 0, 'Học theo học kỳ (10 tháng)', '300.000đ / tháng tự nguyện', '2026-07-27 15:19:40', '2026-07-27 15:19:40'),
(33, 155, 'Hệ đào tạo THPT chính quy chuẩn quốc gia', 'Giáo dục toàn diện văn hóa kết hợp với các chương trình tìm hiểu di sản lịch sử Cổ Loa, rèn luyện kỹ năng sống.', 'https://images.unsplash.com/photo-1546410531-bb4caa6b424d?auto=format&fit=crop&w=800&q=80', NULL, 0, 0, '3 năm', 'Học phí công lập chuẩn', '2026-07-27 15:19:40', '2026-07-27 15:19:40'),
