(1, 39, '02/GCNATTPNL-KT', 'PHÒNG KINH TẾ HUYỆN ĐÔNG ANH', '2017-04-25', '2020-04-25', '/uploads/certificates/default-cert.jpg', 'active', '2026-07-31 03:26:16', '2026-07-31 03:26:16');
INSERT INTO `food_tours` (`id`, `user_id`, `name`, `slug`, `description`, `duration`, `distance`, `budget`, `difficulty`, `best_time`, `popularity`, `mood`, `thumbnail`, `story`, `status`, `is_ai_generated`, `shared_at`, `expires_at`, `created_at`, `updated_at`) VALUES
(1, NULL, 'Hành trình Hương vị Cổ Loa - Khám phá Chợ & Ẩm thực OCOP Đông Anh', 'hanh-trinh-huong-vi-co-loa-kham-pha-cho-am-thuc-ocop-dong-anh-8cd9f', 'Đắm mình vào không khí chợ truyền thống, khám phá những sản phẩm OCOP tinh hoa và kết thúc với món chè ngọt ngào đặc trưng của vùng đất Đông Anh.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'cheap', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Để trải nghiệm trọn vẹn bản sắc văn hóa và ẩm thực Đông Anh với ngân sách \'cheap\', chúng ta sẽ bắt đầu tại Chợ Sa cổ kính, nơi nhịp sống địa phương và câu chuyện lịch sử hòa quyện. Tiếp đó, khám phá hương vị OCOP độc đáo từ sản phẩm được chứng nhận của vùng. Cuối cùng, một bát chè truyền thống sẽ là điểm dừng chân hoàn hảo để kết thúc hành trình.', 'draft', 1, NULL, NULL, '2026-06-24 06:47:28', '2026-06-24 06:47:28'),
(2, 4, 'Hành trình thư thái khám phá di sản và tinh hoa OCOP Đông Anh', 'hanh-trinh-thu-thai-kham-pha-di-san-va-tinh-hoa-ocop-dong-anh-09dc2', 'Hành trình đưa bạn rời xa ồn ào đô thị, hòa mình vào không gian cổ kính của Cổ Loa, thưởng thức nét ẩm thực và sản vật địa phương. Trải nghiệm các sản phẩm OCOP tinh hoa, mang đậm dấu ấn bản địa trong một không gian thư thái, yên bình.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Đông Anh không chỉ có những con đường tấp nập mà còn ẩn chứa những giá trị văn hóa, lịch sử sâu sắc. Lộ trình này được thiết kế để bạn vừa khám phá kinh đô xưa, vừa chạm tới những nét ẩm thực và sản vật đặc trưng của vùng đất Cổ Loa. Đặc biệt, chúng tôi sẽ ưu tiên những sản phẩm OCOP chất lượng, thể hiện sự sáng tạo và tinh hoa của người dân địa phương, mang đến trải nghiệm \'chill\' đúng điệu.', 'draft', 1, NULL, NULL, '2026-07-24 04:28:03', '2026-07-24 04:28:03'),
(3, 4, 'Tuấn Anh Nguyễn', 'tuan-anh-nguyen-f3035', 'wwwwwwwwwwwwwwwww', '2.5 giờ', '5.0 km', '200.000đ', '☕ Nhẹ nhàng', '18:00 - 22:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', NULL, 'saved', 0, NULL, NULL, '2026-07-24 04:29:07', '2026-07-24 04:29:07'),
(4, 1, 'Hành trình Đông Anh Cổ kính & Tinh hoa OCOP', 'hanh-trinh-dong-anh-co-kinh-tinh-hoa-ocop-0ee2c', 'Một hành trình thư thái khám phá những di tích lịch sử lâu đời và thưởng thức hương vị đặc sản OCOP mang đậm bản sắc văn hóa của Đông Anh.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Để tìm về sự bình yên và kết nối với văn hóa địa phương, chúng ta sẽ bắt đầu tại Khu Di Tích Cổ Loa huyền thoại, nơi lắng đọng những câu chuyện lịch sử. Tiếp đó, đắm mình vào không khí sống động của Chợ Sa truyền thống, nơi giao thoa của văn hóa và ẩm thực. Cuối cùng, khép lại chuyến đi bằng việc thưởng thức những món bánh OCOP tinh hoa, mang đậm hương vị quê hương.', 'draft', 1, NULL, NULL, '2026-07-26 16:43:55', '2026-07-26 16:43:55'),
(5, 4, 'Đông Anh Chill: Vị Ngon OCOP & Chuyện Chợ Xưa', 'dong-anh-chill-vi-ngon-ocop-chuyen-cho-xua-9bf39', 'Khám phá Đông Anh một cách thư thái qua hành trình ẩm thực kết hợp văn hóa, ưu tiên các sản phẩm OCOP tinh hoa bản địa. Tận hưởng không khí bình dị, thưởng thức đặc sản và kết thúc bằng món tráng miệng ngọt ngào.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Bắt đầu chuyến đi bằng việc khám phá hương vị tinh hoa từ sản phẩm OCOP địa phương, nơi lưu giữ những nét ẩm thực truyền thống của Đông Anh. Tiếp đó, bạn sẽ đắm mình vào không gian Chợ Sa cổ kính, tìm hiểu về cuộc sống và ẩm thực của người dân Cổ Loa từ ngàn xưa. Kết thúc bằng một món chè thanh mát để thư giãn, hoàn thành một ngày trải nghiệm nhẹ nhàng, đậm chất Đông Anh.', 'draft', 1, NULL, NULL, '2026-07-26 16:44:04', '2026-07-26 16:44:04'),
(6, 1, 'Hành trình Hương vị Cổ Loa - Chầm chậm Đông Anh', 'hanh-trinh-huong-vi-co-loa-cham-cham-dong-anh-5a921', 'Khám phá vẻ đẹp lịch sử và thưởng thức tinh hoa ẩm thực bản địa Đông Anh một cách thư thái, nhẹ nhàng. Một lộ trình hoàn hảo cho những tâm hồn tìm kiếm sự bình yên và hương vị truyền thống.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Bắt đầu hành trình tại Cổ Loa, nơi lịch sử ngàn năm vang vọng, để cảm nhận hồn cốt của vùng đất. Tiếp nối, ta sẽ tìm đến những giá trị ẩm thực truyền thống, đặc biệt là sản phẩm OCOP, để nếm thử và hiểu thêm về công sức người dân. Cuối cùng, một món tráng miệng thanh mát sẽ khép lại chuyến đi, để lại dư vị ngọt ngào và những kỷ niệm khó quên về Đông Anh.', 'draft', 1, NULL, NULL, '2026-07-26 17:13:34', '2026-07-26 17:13:34'),
(7, 1, 'Hành trình Vòng Ốc Cổ Loa: Chinh phục quá khứ, thưởng thức đặc sản', 'hanh-trinh-vong-oc-co-loa-chinh-phuc-qua-khu-thuong-thuc-dac-san-df317', 'Khám phá di sản ngàn năm của Đông Anh tại thành Cổ Loa, sau đó hòa mình vào không khí sôi động của chợ truyền thống và kết thúc bằng những thức quà OCOP tinh túy. Lộ trình này sẽ đưa bạn từ lịch sử hào hùng đến nét ẩm thực đậm đà bản sắc trong một buổi chiều \'chill\' đầy ý nghĩa.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Để thực sự cảm nhận Đông Anh, không thể bỏ qua trái tim văn hóa - Khu Di Tích Cổ Loa, nơi huyền thoại và lịch sử giao thoa. Tiếp nối dòng chảy cuộc sống, Chợ Sa kề bên sẽ là điểm dừng chân lý tưởng để bạn hòa mình vào nhịp sống thường nhật và khám phá những hương vị địa phương. Cuối cùng, ghé thăm cơ sở OCOP là cách tuyệt vời để thưởng thức và mang về những sản phẩm tinh hoa, khép lại một hành trình trải nghiệm sâu sắc và đáng nhớ.', 'draft', 1, NULL, NULL, '2026-07-26 17:17:44', '2026-07-26 17:17:44'),
(8, 2, 'Đông Anh Chill: Du ngoạn Lịch sử & Ẩm thực OCOP', 'dong-anh-chill-du-ngoan-lich-su-am-thuc-ocop-88364', 'Một hành trình thư thái khám phá những giá trị văn hóa lịch sử lâu đời của Cổ Loa, kết hợp với trải nghiệm ẩm thực bản địa độc đáo từ các sản phẩm OCOP tinh hoa.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Để có một buổi chiều \'chill\' đúng điệu, chúng ta sẽ bắt đầu tại trái tim văn hóa của Đông Anh là Thành Cổ Loa huyền thoại. Tiếp đó, đắm mình vào không khí truyền thống tại Chợ Sa cổ kính để cảm nhận nhịp sống địa phương. Cuối cùng, khép lại hành trình bằng cách thưởng thức hương vị đặc sản OCOP, thể hiện sự tinh túy trong ẩm thực Đông Anh.', 'draft', 1, NULL, NULL, '2026-07-27 08:33:19', '2026-07-27 08:33:19'),
(9, 1, 'Hành trình Cổ Loa An Yên & Hương Vị Bản Địa', 'hanh-trinh-co-loa-an-yen-huong-vi-ban-dia-75548', 'Một chuyến đi nhẹ nhàng, kết hợp khám phá di tích lịch sử Cổ Loa, trải nghiệm chợ truyền thống và thưởng thức ẩm thực đặc trưng Đông Anh trong không khí thư thái.', '2.5 giờ', '5.0 km', '350.000đ', '✨ Lộ trình AI', '17:00 - 21:00', 'Mới tạo', 'chill', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'Đông Anh không chỉ có những món ăn ngon mà còn ẩn chứa chiều sâu văn hóa lịch sử. Lộ trình này sẽ đưa bạn từ những câu chuyện cổ xưa tại Cổ Loa, hòa mình vào nhịp sống bản địa ở Chợ Sa, nơi bạn có thể tìm thấy tinh hoa ẩm thực OCOP, và khép lại bằng sự thanh tịnh bên ly trà. Tất cả đều gói gọn trong một hành trình \'chill\' đúng nghĩa.', 'draft', 1, NULL, NULL, '2026-08-02 16:02:37', '2026-08-02 16:02:37');
INSERT INTO `food_tour_stops` (`id`, `food_tour_id`, `eatery_id`, `stop_order`, `stop_story`, `estimated_time`, `created_at`, `updated_at`) VALUES
(1, 1, 3, 1, 'Dạo quanh Chợ Sa (Cổ Loa) vào phiên chợ để cảm nhận không khí buôn bán tấp nập, tìm mua các loại nông sản tươi ngon đặc trưng của vùng như hành lá, khoai tây (có thể là sản phẩm OCOP từ HTX Cổ Loa) và hòa mình vào nét văn hóa địa phương. Bạn có thể mua một ít trái cây hoặc đồ ăn vặt bình dân với chi phí khoảng 50.000 - 80.000 VNĐ.', '45 phút', '2026-06-24 06:47:28', '2026-06-24 06:47:28'),
(2, 3, 2, 1, '', '45 phút', '2026-07-24 04:29:07', '2026-07-24 04:29:07'),
(3, 3, 3, 2, '', '45 phút', '2026-07-24 04:29:07', '2026-07-24 04:29:07'),
(4, 7, 3, 1, 'Dành thời gian dạo quanh các di tích lịch sử như Đền Thượng, Đình Ngự Triều Di Quy và Giếng Ngọc. Hãy lắng nghe những câu chuyện huyền thoại về vua An Dương Vương và nỏ thần Kim Quy để cảm nhận trọn vẹn giá trị văn hóa.', '45 phút', '2026-07-26 17:17:44', '2026-07-26 17:17:44'),
(5, 7, 3, 2, 'Thăm Chợ Sa vào phiên chợ để cảm nhận không khí buôn bán tấp nập của khu chợ cổ truyền. Dạo quanh các gian hàng, thưởng thức những món quà vặt địa phương, và ngắm nhìn cuộc sống đời thường của người dân Cổ Loa.', '45 phút', '2026-07-26 17:17:44', '2026-07-26 17:17:44'),
(6, 7, 3, 3, 'Khám phá và mua sắm các sản phẩm OCOP \'Bánh gạo lứt\' và \'Bánh vừng vòng\' của Công ty TNHH Hoàng Chiến Thắng. Đây là những món quà vặt truyền thống thơm ngon, bổ dưỡng, rất phù hợp để nhâm nhi khi \'chill\' hoặc làm quà tặng.', '45 phút', '2026-07-26 17:17:44', '2026-07-26 17:17:44'),
(7, 8, 49, 1, 'Dạo bước khám phá Thành Cổ Loa huyền thoại, chiêm ngưỡng kiến trúc độc đáo và tìm hiểu về lịch sử An Dương Vương trong không gian tĩnh lặng, đầy chất thơ.', '45 phút', '2026-07-27 08:33:19', '2026-07-27 08:33:19'),
(8, 8, 19, 2, 'Đắm mình vào không khí chợ truyền thống lâu đời của Chợ Sa (Cổ Loa), giao lưu với người dân địa phương và tìm kiếm những món quà vặt, sản vật đặc trưng của vùng đất cổ.', '45 phút', '2026-07-27 08:33:19', '2026-07-27 08:33:19'),
(9, 8, 41, 3, 'Thưởng thức Giò lụa, Chả lụa OCOP trứ danh của Đông Anh. Đây là cơ hội tuyệt vời để cảm nhận hương vị truyền thống tinh túy và mua về làm quà cho gia đình, bạn bè.', '45 phút', '2026-07-27 08:33:19', '2026-07-27 08:33:19'),
(10, 9, 49, 1, 'Dạo bước khám phá kiến trúc độc đáo của thành ốc và lắng nghe những câu chuyện huyền thoại về An Dương Vương, nỏ thần Kim Quy. Hoạt động nhẹ nhàng, giúp thư thái tâm hồn mà không tốn kém.', '45 phút', '2026-08-02 16:02:37', '2026-08-02 16:02:37'),
(11, 9, 19, 2, 'Đắm mình vào không khí chợ truyền thống, tìm mua các đặc sản địa phương. Bạn có thể hỏi mua Giò lụa, Chả lụa (từ Cơ sở sản xuất thực phẩm Liêm Hiệp) hoặc các loại bánh OCOP như Bánh gạo lứt, Bánh vừng vòng của Công ty TNHH Hoàng Chiến Thắng để nhâm nhi tại chỗ hoặc mang về làm quà. Đừng quên thử thêm các món ăn vặt dân dã khác của chợ.', '45 phút', '2026-08-02 16:02:37', '2026-08-02 16:02:37'),
(12, 9, 5, 3, 'Kết thúc hành trình bằng một buổi thư giãn tại đây, thưởng thức những ly trà thanh mát hoặc các món chè ngọt ngào, giúp dịu lại tâm hồn sau những giờ khám phá. Một điểm dừng chân lý tưởng để \'chill\' và tận hưởng không gian yên bình.', '45 phút', '2026-08-02 16:02:37', '2026-08-02 16:02:37');
INSERT INTO `friendships` (`id`, `user_id`, `friend_id`, `status`, `created_at`, `updated_at`) VALUES
(1, 4, 1, 'accepted', '2026-07-13 08:03:32', '2026-07-13 08:03:41');
