(1, 16, NULL, 'BQL Chợ Mạch Tràng', 'admin', NULL, 'Chào mừng quý khách và bà con tiểu thương tham gia Phòng Chat Chợ Số 4.0 Mạch Tràng! Chúc bà con buôn may bán đắt.', NULL, NULL, NULL, NULL, '2026-07-23 08:28:59', '2026-07-23 08:28:59'),
(2, 16, NULL, 'Chủ sạp Cô Năm', 'merchant', 'Sạp rau quả Cô Năm', 'Rau cải ngọt Vân Nội sáng nay nhà em vừa hái xong, tươi rói không hóa chất nhé cả nhà ơi!', NULL, NULL, NULL, NULL, '2026-07-23 08:28:59', '2026-07-23 08:28:59'),
(3, 16, NULL, 'Nguyễn Minh', 'user', NULL, 'Cô Năm ơi tí tầm 5h chiều con đi làm về qua lấy 1kg rau cải với 1 quả bí đỏ nha cô.', NULL, NULL, NULL, NULL, '2026-07-23 08:28:59', '2026-07-23 08:28:59'),
(4, 16, NULL, 'Chủ sạp Cô Năm', 'merchant', 'Sạp rau quả Cô Năm', 'Ok nha Minh ơi, cô để sẵn bọc riêng cho con nhé!', NULL, NULL, NULL, NULL, '2026-07-23 08:28:59', '2026-07-23 08:28:59'),
