(10, 16, 4, 'Thành viên Đông Anh', 'user', NULL, 'Giá bao nhiêu vậy ạ?', NULL, NULL, 'Gian hàng Ăn uống Cô Sinh', NULL, '2026-07-23 08:42:28', '2026-07-23 08:42:28'),
(11, 16, 4, 'Thành viên Đông Anh', 'user', NULL, 'Hàng có sẵn để qua lấy luôn không ạ?', NULL, NULL, 'Gian hàng Ăn uống Cô Sinh', NULL, '2026-07-23 08:42:29', '2026-07-23 08:42:29'),
