INSERT INTO `ocop_products` (`id`, `eatery_id`, `user_id`, `stall_name`, `seller_name`, `seller_phone`, `bank_name`, `bank_account`, `bank_holder`, `qr_code_path`, `name`, `price`, `unit`, `description`, `image_path`, `star_rating`, `created_at`, `updated_at`, `heritage_year`, `story`, `artisans`, `fun_fact`, `audio_narrative`, `ingredients`, `timeline`) VALUES
(1, 34, 187, 'HTX nông nghiệp dược liệu công nghệ cao KOVI', 'Hợp tác xã nông nghiệp dược liệu công nghệ cao KOVI', NULL, 'MBBank', '0987654321', 'HTX NÔNG NGHIỆP DƯỢC LIỆU CÔNG NGHỆ CAO KOVI', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HTX+N%C3%94NG+NGHI%E1%BB%86P+D%C6%AF%E1%BB%A2C+LI%E1%BB%86U+C%C3%94NG+NGH%E1%BB%86+CAO+KOVI&addInfo=TT+HTX+n%C3%B4ng+nghi%E1%BB%87p+d%C6%B0%E1%BB%A3c+li%E1%BB%87u+c%C3%B4ng+ngh%E1%BB%87+cao+KOVI', 'Đông trùng hạ thảo tươi', 80000.00, 'hộp', 'Chủ thể sản xuất: Hợp tác xã nông nghiệp dược liệu công nghệ cao KOVI\nCăn cứ pháp lý & Địa chỉ: Thôn Lộc Hà, xã Đông Anh; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2022)\nThông tin thanh toán: 111002871148 Ngân hàng Viettinbank chi nhánh Đồng Dầu\nKênh phân phối: https://s.shopee.vn/6AjpVmXp3d?share_channel_code=8\n\nĐịa chỉ nhà máy: Thôn Lộc Hà, xã Mai Lâm (xã Đông Anh), huyện Đông Anh, TP. Hà Nội\nTiêu chuẩn nhà máy: Quy trình sản xuất khép kín đạt chứng nhận an toàn thực phẩm HACCP và tiêu chuẩn dược phẩm GMP.\nGian hàng chính hãng Shopee Mall: https://s.shopee.vn/8AIgVmXp3d?share_channel_code=8\nSố tài khoản: 111002871148 tại Ngân hàng Vietinbank chi nhánh Đông Anh\n\nThông tin chi tiết về Đông trùng hạ thảo tươi KOVI:\n- Đóng gói: Hũ chuyên dụng dung tích 700ml (trọng lượng thực tế phần nấm tươi 150g).\n- Trạng thái: Sợi nấm màu vàng cam đậm, mọc đều trên đế sinh khối tươi (gạo lứt, nước dừa tươi, nhộng tằm xay...).\n- Dược chất sinh học: Giữ trọn vẹn lượng vitamin tươi tự nhiên và hoạt chất sinh học Cordycepin & Adenosine hàm lượng cao.\n\nHướng dẫn sử dụng & Bảo quản:\n1. Hãm trà: Dùng 3 - 5 sợi nấm tươi hãm với nước ấm (70-80°C), uống nước và ăn cả sợi nấm.\n2. Chế biến món ăn: Thả vào cháo, lẩu, gà hầm, chim bồ câu tiềm khi món ăn đã gần chín.\n3. Ngâm mật ong: Ngâm cả đế và sợi tươi với mật ong nguyên chất để dùng dần hằng ngày.\n4. Bảo quản: Do là sản phẩm tươi, hũ nấm BẮT BUỘC bảo quản ngăn mát tủ lạnh (2 - 4°C) và nên sử dụng trong 10 - 15 ngày sau khi mở nắp.', 'https://media.xadonganh.com/ocop/1785483918_Uf4r3vOz.webp', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', 'Năm 2022', 'Đông trùng hạ thảo tươi KOVI là niềm tự hào dược liệu công nghệ cao của HTX Nông nghiệp dược liệu công nghệ cao KOVI tại thôn Lộc Hà, xã Mai Lâm, huyện Đông Anh, Hà Nội. Tác phẩm sinh học này ứng dụng chuyển giao khoa học công nghệ nuôi cấy tiên tiến từ Hàn Quốc với chủng giống F1 thuần khiết bản quyền.\n\nTrong quy trình sản xuất khép kín đạt chuẩn HACCP và GMP quốc tế, từng hũ nấm tươi KOVI phát triển trên lớp đế sinh khối tự nhiên giàu dinh dưỡng gồm gạo lứt, nước dừa tươi và nhộng tằm xay. Nhờ không qua xử lý nhiệt sấy, đông trùng hạ thảo tươi giữ trọn vẹn hàm lượng Cordycepin, Adenosine cùng các vitamin nhạy cảm nhiệt, hỗ trợ tăng cường hệ miễn dịch, bồi bổ cơ thể suy nhược và cải thiện chức năng gan, thận, tim mạch cho người tiêu dùng.', 'Chuyên gia Kỹ thuật Ngô Quốc Hưng & Đội ngũ HTX KOVI (Thôn Lộc Hà, Mai Lâm, Đông Anh)', 'Quy trình sấy thăng hoa ở nhiệt độ -40 độ C giúp giữ nguyên 99% hàm lượng dược chất Cordycepin và Adenosine quý giá.', 'Đông trùng hạ thảo tươi KOVI là sản phẩm dược liệu công nghệ cao xuất sắc đạt chứng nhận OCOP 4 sao Cấp Thành phố Hà Nội của HTX Nông nghiệp dược liệu công nghệ cao KOVI, huyện Đông Anh. Ứng dụng công nghệ sinh học chuẩn Hàn Quốc và nhà máy đạt chuẩn HACCP, GMP, hũ nấm tươi 150g giữ trọn vẹn vitamin cùng lượng Cordycepin và Adenosine tươi nguyên chất, giúp bồi bổ sức khỏe, tăng cường hệ miễn dịch và hô hấp.', '[\"Ch\\u1ee7ng n\\u1ea5mCordyceps militaris F1 H\\u00e0n Qu\\u1ed1c\",\"\\u0110\\u1ebf sinh kh\\u1ed1i g\\u1ea1o l\\u1ee9t & n\\u01b0\\u1edbc d\\u1eeba t\\u01b0\\u01a1i\",\"Nh\\u1ed9ng t\\u1eb1m xay t\\u01b0\\u01a1i dinh d\\u01b0\\u1ee1ng\",\"Ho\\u1ea1t ch\\u1ea5t sinh h\\u1ecdc Cordycepin & Adenosine t\\u01b0\\u01a1i\"]', '[{\"year\":\"Chuy\\u1ec3n giao\",\"event\":\"KOVI ti\\u1ebfp nh\\u1eadn chuy\\u1ec3n giao c\\u00f4ng ngh\\u1ec7 nu\\u00f4i c\\u1ea5y \\u0110\\u00f4ng tr\\u00f9ng h\\u1ea1 th\\u1ea3o F1 thu\\u1ea7n khi\\u1ebft t\\u1eeb H\\u00e0n Qu\\u1ed1c.\"},{\"year\":\"Chu\\u1ea9n HACCP & GMP\",\"event\":\"X\\u00e2y d\\u1ef1ng nh\\u00e0 v\\u1ec7 sinh sinh h\\u1ecdc \\u0111\\u1ea1t ti\\u00eau chu\\u1ea9n qu\\u1ed1c t\\u1ebf HACCP v\\u00e0 GMP d\\u01b0\\u1ee3c ph\\u1ea9m t\\u1ea1i \\u0110\\u00f4ng Anh.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"S\\u1ea3n ph\\u1ea9m \\u0110\\u00f4ng tr\\u00f9ng h\\u1ea1 th\\u1ea3o t\\u01b0\\u01a1i \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"},{\"year\":\"M\\u00e3 QR Truy xu\\u1ea5t\",\"event\":\"T\\u00edch h\\u1ee3p tem OCOP 4 sao v\\u00e0 m\\u00e3 QR truy xu\\u1ea5t ngu\\u1ed3n g\\u1ed1c ch\\u1ed1ng h\\u00e0ng gi\\u1ea3 ch\\u00ednh h\\u00e3ng.\"}]'),
(2, 34, 187, 'HTX nông nghiệp dược liệu công nghệ cao KOVI', 'Hợp tác xã nông nghiệp dược liệu công nghệ cao KOVI', NULL, 'MBBank', '0987654321', 'HTX NÔNG NGHIỆP DƯỢC LIỆU CÔNG NGHỆ CAO KOVI', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HTX+N%C3%94NG+NGHI%E1%BB%86P+D%C6%AF%E1%BB%A2C+LI%E1%BB%86U+C%C3%94NG+NGH%E1%BB%86+CAO+KOVI&addInfo=TT+HTX+n%C3%B4ng+nghi%E1%BB%87p+d%C6%B0%E1%BB%A3c+li%E1%BB%87u+c%C3%B4ng+ngh%E1%BB%87+cao+KOVI', 'Đông trùng hạ thảo khô 25g loại 1', 350000.00, 'hộp', 'Chủ thể sản xuất: Hợp tác xã nông nghiệp dược liệu công nghệ cao KOVI\nCăn cứ pháp lý & Địa chỉ: Thôn Lộc Hà, xã Đông Anh; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2022)\nKênh phân phối: https://shopee.vn/%C4%90%C3%B4ng-tr%C3%B9ng-h%E1%BA%A1-th%E1%BA%A3o-KOVI-s%E1%BA%A5y-kh%C3%B4-th%C4%83ng-hoa-25g-H%C3%A0ng-Vip-1-i.893601216.20059462131?extraParams=%7B%22display_model_id%22%3A39158329474%2C%22model_selection_logic%22%3A3%7D\n\nĐịa chỉ nhà máy: Thôn Lộc Hà, xã Đông Anh, TP. Hà Nội\nCông nghệ: Sấy thăng hoa nhiệt độ âm sâu (-40°C) chuẩn Hoa Kỳ bảo toàn 99% dược tính sinh học.\nQuy cách: Hũ thủy tinh 25g loại 1 sợi nguyên vẹn dài đẹp.\nSố tài khoản: 111002871148 tại Ngân hàng Vietinbank chi nhánh Đông Anh\n\nThông tin chi tiết sản phẩm Đông trùng hạ thảo khô 25g loại 1:\n- Công nghệ sấy thăng hoa âm sâu (-40°C) giúp tinh thể nước thăng hoa hoàn toàn mà không làm biến tính các dược chất quý (Cordycepin, Adenosine, Axit amin).\n- Sợi nấm không bị teo nhỏ hay xỉn màu, giữ nguyên hình dáng mập mạp và màu vàng cam đậm bắt mắt.\n- Hạn sử dụng lên tới 2 năm ở nhiệt độ phòng, rất tiện lợi bảo quản và làm quà biếu sang trọng.\n\nHướng dẫn sử dụng & Liều dùng (1 - 3g/ngày):\n1. Pha trà dưỡng sinh: Cho 5 - 10 cọng nấm khô vào bình, hãm với nước nóng (80 - 90°C) trong 10 phút. Uống nước trà hằng ngày và ăn luôn cả sợi nấm.\n2. Ngâm mật ong: Ngâm 10g - 15g sợi khô với 1 lít mật ong nguyên chất. Sau 7 - 10 ngày dùng được, mỗi ngày uống 1 - 2 thìa cà phê pha nước ấm vào buổi sáng.\n3. Chế biến món ăn: Dùng hầm gà, chim bồ câu hoặc nấu cháo. Chỉ thả nấm vào khi món ăn đã gần chín để tránh làm tiêu hao vitamin.\n4. Bảo quản: Nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785484446_ajaP1K0x.webp', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', 'Năm 2022', 'Đông trùng hạ thảo khô 25g loại 1 KOVI là phiên bản dược liệu sấy thăng hoa cao cấp của HTX Nông nghiệp dược liệu công nghệ cao KOVI tại thôn Lộc Hà, xã Đông Anh. Sản phẩm xuất sắc đạt chứng nhận OCOP 4 sao Cấp Thành Phố Hà Nội.\n\nBào chế từ 100% sợi nấm tươi nguyên con dài đẹp mọc trên đế sinh khối chất lượng cao, KOVI ứng dụng công nghệ sấy thăng hoa nhiệt độ âm sâu (-40°C) tiên tiến của Mỹ. Nhờ vậy, từng sợi nấm giữ nguyên vẹn 99% hàm lượng dược chất sinh học Cordycepin và Adenosine quý giá, màu sắc vàng cam đậm mập mạp bắt mắt và thời hạn bảo quản kéo dài đến 2 năm ở nhiệt độ phòng. Đây là thức quà sức khỏe sang trọng dành tặng đối tác và gia đình.', 'Đội ngũ Chuyên gia Dược liệu HTX KOVI (Thôn Lộc Hà, Đông Anh)', 'Quy trình sấy thăng hoa ở nhiệt độ -40 độ C giúp giữ nguyên 99% hàm lượng dược chất Cordycepin và Adenosine quý giá.', 'Đông trùng hạ thảo khô 25g loại 1 KOVI là sản phẩm cao cấp đạt chứng nhận OCOP 4 sao Cấp Thành phố Hà Nội của HTX Nông nghiệp dược liệu công nghệ cao KOVI, huyện Đông Anh. Được bào chế từ sợi nấm tươi nguyên con mập mạp qua công nghệ sấy thăng hoa âm sâu 40 độ âm của Mỹ, sản phẩm giữ trọn vẹn 99 phần trăm dược chất quý Cordycepin và Adenosine, với hạn sử dụng 2 năm ở nhiệt độ phòng, là món quà bồi bổ sức khỏe tuyệt vời cho mọi gia đình.', '[\"100% S\\u1ee3i \\u0110\\u00f4ng tr\\u00f9ng h\\u1ea1 th\\u1ea3o t\\u01b0\\u01a1i s\\u1ea5y th\\u0103ng hoa (-40\\u00b0C)\",\"Ho\\u1ea1t ch\\u1ea5t Cordycepin & Adenosine t\\u1ef1 nhi\\u00ean (99%)\",\"Axit amin & Vitamin kho\\u00e1ng ch\\u1ea5t sinh h\\u1ecdc\"]', '[{\"year\":\"C\\u00f4ng ngh\\u1ec7 M\\u1ef9\",\"event\":\"KOVI nh\\u1eadp kh\\u1ea9u c\\u00f4ng ngh\\u1ec7 s\\u1ea5y th\\u0103ng hoa \\u00e2m s\\u00e2u (-40\\u00b0C) chu\\u1ea9n Hoa K\\u1ef3 b\\u1ea3o to\\u00e0n 99% d\\u01b0\\u1ee3c ch\\u1ea5t.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"S\\u1ea3n ph\\u1ea9m \\u0110\\u00f4ng tr\\u00f9ng h\\u1ea1 th\\u1ea3o kh\\u00f4 25g lo\\u1ea1i 1 \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"},{\"year\":\"\\u0110\\u00f3ng g\\u00f3i sang tr\\u1ecdng\",\"event\":\"Quy chu\\u1ea9n h\\u0169 th\\u1ee7y tinh cao c\\u1ea5p 25g s\\u1ea5y nguy\\u00ean s\\u1ee3i m\\u1eadp m\\u1ea1p b\\u1ea3o qu\\u1ea3n 2 n\\u0103m.\"}]'),
(3, 34, 187, 'HTX nông nghiệp dược liệu công nghệ cao KOVI', 'Hợp tác xã nông nghiệp dược liệu công nghệ cao KOVI', NULL, 'MBBank', '0987654321', 'HTX NÔNG NGHIỆP DƯỢC LIỆU CÔNG NGHỆ CAO KOVI', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HTX+N%C3%94NG+NGHI%E1%BB%86P+D%C6%AF%E1%BB%A2C+LI%E1%BB%86U+C%C3%94NG+NGH%E1%BB%86+CAO+KOVI&addInfo=TT+HTX+n%C3%B4ng+nghi%E1%BB%87p+d%C6%B0%E1%BB%A3c+li%E1%BB%87u+c%C3%B4ng+ngh%E1%BB%87+cao+KOVI', 'Đông trùng hạ thảo khô 50g loại 1 xếp sợi', 650000.00, 'hộp', 'Chủ thể sản xuất: Hợp tác xã nông nghiệp dược liệu công nghệ cao KOVI\nCăn cứ pháp lý & Địa chỉ: Thôn Lộc Hà, xã Đông Anh; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2022)\n\nĐịa chỉ nhà máy: Thôn Lộc Hà, xã Đông Anh, TP. Hà Nội\nTiêu chuẩn nhà máy: Chuẩn quốc tế HACCP & ISO 22000.\nQuy cách: Hộp/Lọ thủy tinh cao cấp chứa chính xác 50 con Đông trùng ký chủ sấy thăng hoa nguyên con.\nSố tài khoản: 111002871148 tại Ngân hàng Vietinbank chi nhánh Đông Anh\n\nĐiểm vượt trội phân khúc Thượng Hạng VIP 1 (Ký Chủ Nhộng Tằm Nguyên Con):\n- Phương pháp tiêm chủng trực tiếp bào tử nấm Cordyceps militaris vào nhộng tằm dâu sống. Nấm ăn trọn dưỡng chất nhộng tằm và mọc 2-3 quả thể nấm mập mạp.\n- Dược chất mô phỏng tự nhiên: Hàm lượng Cordycepin và Adenosine cao GẤP 1.5 - 2 LẦN so với dạng sợi sinh khối thông thường.\n- Bảo chứng thị giác chống hàng giả: Kết cấu nguyên con nhộng tự nhiên gắn liền sợi nấm rực rỡ không máy móc nào làm giả được.\n\nHướng dẫn sử dụng tối ưu bồi bổ (1 - 2 con/ngày):\n1. Ăn trực tiếp: Ngâm 1 con vào nước ấm (60°C) cho phần nhộng và sợi nấm mềm ra, nhai trực tiếp cả phần con lẫn phần nấm rồi nuốt.\n2. Pha trà thượng hạng: Cho 2 - 3 con vào bình trà giữ nhiệt hãm 10 - 15 phút. Nước trà vàng óng thơm ngát, uống hết nước ăn cả con ký chủ.\n3. Chưng yến bồi bổ: Thả 1 - 2 con ký chủ vào hũ yến sào đảo đều 5 phút trước khi tắt bếp.\n4. Ngâm bình rượu phong thủy: Thả nguyên con vào bình rượu thủy tinh lớn cùng nhân sâm trưng bày phòng khách vô cùng sang trọng.\n5. Mục đích: Phù hợp biếu sếp, đối tác ngoại giao, ông bà cha mẹ hoặc bồi bổ người suy nhược thể trạng nặng.', 'https://media.xadonganh.com/ocop/1785485755_0EoKQRKz.webp', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', 'Năm 2022', 'Đông trùng hạ thảo ký chủ nhộng tằm hộp 50 con KOVI là kiệt tác dược liệu thượng hạng bậc nhất của HTX Nông nghiệp dược liệu công nghệ cao KOVI tại thôn Lộc Hà, xã Đông Anh. Tác phẩm đạt phân hạng OCOP 4 sao Cấp Thành Phố Hà Nội và chứng nhận an toàn thực phẩm quốc tế HACCP, ISO 22000.\n\nSản phẩm được tạo ra bằng kỹ thuật tiêm chủng trực tiếp bào tử nấm Cordyceps militaris vào từng cá thể nhộng tằm dâu tươi sống. Sau khi nấm hấp thụ nguồn dinh dưỡng protein phong phú trực tiếp từ vật chủ và mọc lên những quả thể nấm màu vàng cam rực rỡ, toàn bộ hệ thống nguyên con nhộng lẫn nấm được đưa đi sấy thăng hoa nhiệt độ âm sâu (-40°C) của Mỹ. Quy trình này giúp hàm lượng dược chất Cordycepin & Adenosine cao gấp 1.5 đến 2 lần dạng sinh khối thông thường, mang lại nguồn dinh dưỡng phục hồi thể trạng hoàn hảo cho mọi gia đình.', 'Đội ngũ Chuyên gia Dược liệu HTX KOVI (Thôn Lộc Hà, Đông Anh)', 'Quy trình sấy thăng hoa ở nhiệt độ -40 độ C giúp giữ nguyên 99% hàm lượng dược chất Cordycepin và Adenosine quý giá.', 'Đông trùng hạ thảo ký chủ nhộng tằm hộp 50 con KOVI là phân khúc cao cấp bậc nhất đạt chứng nhận OCOP 4 sao Cấp Thành phố Hà Nội của HTX Nông nghiệp dược liệu công nghệ cao KOVI, huyện Đông Anh. Được chế tác bằng công nghệ tiêm chủng trực tiếp bào tử nấm vào nhộng tằm dâu tươi sống và sấy thăng hoa nguyên con của Mỹ, sản phẩm có hàm lượng dược chất Cordycepin cao gấp 1.5 đến 2 lần thông thường, là thức quà biếu ngoại giao sang trọng và bồi bổ thể trạng chuyên sâu nhất.', '[\"100% \\u0110\\u00f4ng tr\\u00f9ng h\\u1ea1 th\\u1ea3o k\\u00fd ch\\u1ee7 nh\\u1ed9ng t\\u1eb1m t\\u01b0\\u01a1i s\\u1ea5y th\\u0103ng hoa (50 con nguy\\u00ean con)\",\"D\\u01b0\\u1ee3c ch\\u1ea5t sinh h\\u1ecdc Cordycepin & Adenosine cao g\\u1ea5p 1.5-2 l\\u1ea7n\",\"H\\u1ed9p th\\u1ee7y tinh Borosilicate & Bao b\\u00ec qu\\u00e0 bi\\u1ebfu ngo\\u1ea1i giao VIP KOVI\"]', '[{\"year\":\"K\\u1ef9 thu\\u1eadt K\\u00fd ch\\u1ee7\",\"event\":\"KOVI l\\u00e0m ch\\u1ee7 c\\u00f4ng ngh\\u1ec7 ti\\u00eam ch\\u1ee7ng b\\u00e0o t\\u1eed n\\u1ea5m sinh h\\u1ecdc tr\\u00ean nh\\u1ed9ng t\\u1eb1m d\\u00e2u s\\u1ed1ng.\"},{\"year\":\"HACCP & ISO 22000\",\"event\":\"Nh\\u00e0 m\\u00e1y s\\u1ea3n xu\\u1ea5t \\u0111\\u1ea1t chu\\u1ea9n an to\\u00e0n th\\u1ef1c ph\\u1ea9m v\\u00e0 d\\u01b0\\u1ee3c ph\\u1ea9m qu\\u1ed1c t\\u1ebf.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"}]'),
(4, 35, 188, 'Hộ kinh doanh Trần Văn Tần', 'Hộ kinh doanh Trần Văn Tân', NULL, 'MBBank', '0987654321', 'HỘ KINH DOANH TRẦN VĂN TẦN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%98+KINH+DOANH+TR%E1%BA%A6N+V%C4%82N+T%E1%BA%A6N&addInfo=TT+H%E1%BB%99+kinh+doanh+Tr%E1%BA%A7n+V%C4%83n+T%E1%BA%A7n', 'Tượng phật Đại Thế Chí Bồ Tát', NULL, NULL, 'Chủ thể sản xuất: Hộ kinh doanh Trần Văn Tân\nCăn cứ pháp lý & Địa chỉ: Thôn Thạc Quả, xã Đông Anh; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2022)\n\nHộ kinh doanh Trần Văn Tân xin kính chào quý khách!\nĐịa chỉ chế tác: Thôn Thạc Quả, xã Dục Tú, huyện Đông Anh, TP. Hà Nội\nHotline tư vấn & đặt tác phẩm: 0984.248.269\nCơ sở pháp lý: Chứng nhận OCOP 4 sao Cấp Thành phố Hà Nội theo Quyết định số 2008/QĐ-UBND ngày 07/04/2023.\n\nThông tin chi tiết về Tượng Phật Đại Thế Chí Bồ Tát:\n- Tác phẩm chạm khắc gỗ mỹ nghệ thủ công tinh xảo, thể hiện tay nghề đỉnh cao của nghệ nhân làng nghề Đông Anh.\n- Chất liệu: Gỗ quý nguyên khối tuyển chọn (Gỗ Hương/Gụ/Trắc), thớ gỗ mịn, không mối mọt, bề mặt đánh bóng vecni tự nhiên hoặc sơn son thếp vàng/dát vàng trang nghiêm.\n- Kỹ nghệ chế tác: Đục thô và chạm bong (chạm nổi khối) thủ công tỉ mỉ từng chi tiết diện mặt thánh triết, nếp áo rủ mềm mại và chuỗi ngọc anh lạc.\n\nHướng dẫn bài trí & Bảo quản:\n- Bài trí trong bộ Tây Phương Tam Thánh (đặt bên tay phải Đức Phật A Di Đà) tại phòng thờ gia đình, nhà thờ họ hoặc không gian tâm linh.\n- Bảo quản nơi khô ráo, thoáng mát, tránh độ ẩm cao và ánh nắng trực tiếp chiếu vào sản phẩm gỗ.', 'https://media.xadonganh.com/ocop/1785471806_SjVtul0o.jpg', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2022', 'Tượng Phật Đại Thế Chí Bồ Tát là kiệt tác điêu khắc gỗ mỹ nghệ thủ công của Hộ kinh doanh Trần Văn Tân tại thôn Thạc Quả, xã Dục Tú, huyện Đông Anh – vùng đất giàu truyền thống chạm khắc gỗ của xứ Kinh Bắc. Tác phẩm đạt chứng nhận OCOP 4 sao Cấp Thành phố Hà Nội.\n\nTrong giáo lý Phật giáo Đại thừa, Đại Thế Chí Bồ Tát là vị Bồ Tát đại diện cho Ánh Sáng Trí Tuệ (Đại Trí), dùng năng lực trí tuệ chiếu soi giúp chúng sinh dập tắt phiền não và hướng về sự an lạc. Tác phẩm thể hiện hình tượng Ngài tay cầm hoa sen xanh (Thanh liên) thanh tịnh, thân đeo chuỗi ngọc anh lạc và vương miện chạm bình tịnh thủy tinh xảo.\n\nBằng đôi bàn tay khéo léo và tâm huyết của người thợ làng nghề Đông Anh, từng đường đục chạm trên thớ gỗ quý đã thổi hồn vào pho tượng, vừa bảo tồn giá trị nghệ thuật chạm khắc gỗ cổ truyền vừa mang lại giá trị tâm linh sâu sắc cho mọi gia đình.', 'Nghệ nhân Trần Văn Tân (Thôn Thạc Quả, Xã Dục Tú, Huyện Đông Anh)', NULL, 'Tượng Phật Đại Thế Chí Bồ Tát là tác phẩm điêu khắc gỗ mỹ nghệ xuất sắc đạt chứng nhận OCOP 4 sao Cấp Thành phố Hà Nội của Hộ kinh doanh Trần Văn Tân, thôn Thạc Quả, xã Dục Tú, huyện Đông Anh. Được chế biến từ nguồn gỗ quý nguyên khối đục chạm thủ công tỉ mỉ, pho tượng khắc họa sinh động Ngài tay cầm hoa sen xanh biểu thị cho ánh sáng trí tuệ dập tắt phiền não. Đây là tác phẩm nghệ thuật tâm linh đỉnh cao, tôn vinh nét đẹp mỹ nghệ cổ truyền Đông Anh.', '[\"G\\u1ed7 qu\\u00fd nguy\\u00ean kh\\u1ed1i ch\\u1ecdn l\\u1ecdc (H\\u01b0\\u01a1ng\\/G\\u1ee5\\/Tr\\u1eafc)\",\"Ch\\u1ea1m bong n\\u1ed5i kh\\u1ed1i th\\u1ee7 c\\u00f4ng\",\"S\\u01a1n th\\u1ebfp v\\u00e0ng \\/ Vecni t\\u1ef1 nhi\\u00ean\",\"Ph\\u00e1p kh\\u00ed Hoa Sen Xanh (Thanh li\\u00ean)\"]', '[{\"year\":\"Truy\\u1ec1n th\\u1ed1ng\",\"event\":\"H\\u1ed9 kinh doanh Tr\\u1ea7n V\\u0103n T\\u00e2n g\\u00ecn gi\\u1eef v\\u00e0 ph\\u00e1t tri\\u1ec3n ngh\\u1ec7 thu\\u1eadt \\u0111i\\u00eau kh\\u1eafc g\\u1ed7 m\\u1ef9 ngh\\u1ec7 t\\u1ea1i l\\u00e0ng ngh\\u1ec1 Th\\u1ea1c Qu\\u1ea3, D\\u1ee5c T\\u00fa.\"},{\"year\":\"T\\u00e1c ph\\u1ea9m\",\"event\":\"Ho\\u00e0n th\\u00e0nh t\\u00e1c ph\\u1ea9m T\\u01b0\\u1ee3ng Ph\\u1eadt \\u0110\\u1ea1i Th\\u1ebf Ch\\u00ed B\\u1ed3 T\\u00e1t ch\\u1ea1m kh\\u1eafc th\\u1ee7 c\\u00f4ng nguy\\u00ean kh\\u1ed1i tinh x\\u1ea3o.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"\\u0110\\u01b0\\u1ee3c UBND Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i c\\u00f4ng nh\\u1eadn \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao c\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Q\\u0110 s\\u1ed1 2008\\/Q\\u0110-UBND.\"},{\"year\":\"T\\u00f4n vinh\",\"event\":\"T\\u00e1c ph\\u1ea9m tham gia tri\\u1ec3n l\\u00e3m, t\\u00f4n vinh gi\\u00e1 tr\\u1ecb m\\u1ef9 ngh\\u1ec7 t\\u00e2m linh c\\u1ee7a l\\u00e0ng ngh\\u1ec1 \\u0111i\\u00eau kh\\u1eafc \\u0110\\u00f4ng Anh.\"}]'),
(5, 35, 188, 'Hộ kinh doanh Trần Văn Tần', 'Hộ kinh doanh Trần Văn Tân', NULL, 'MBBank', '0987654321', 'HỘ KINH DOANH TRẦN VĂN TẦN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%98+KINH+DOANH+TR%E1%BA%A6N+V%C4%82N+T%E1%BA%A6N&addInfo=TT+H%E1%BB%99+kinh+doanh+Tr%E1%BA%A7n+V%C4%83n+T%E1%BA%A7n', 'Song ngưu sinh tài', NULL, NULL, 'Chủ thể sản xuất: Hộ kinh doanh Trần Văn Tân\nCăn cứ pháp lý & Địa chỉ: Thôn Thạc Quả, xã Đông Anh; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2022)\n\nHộ kinh doanh Trần Văn Tân xin kính chào quý khách!\nĐịa chỉ chế tác: Thôn Thạc Quả, xã Dục Tú, huyện Đông Anh, TP. Hà Nội\n\nThông tin chi tiết về tác phẩm mỹ nghệ phong thủy Song ngưu sinh tài:\n- Chất liệu: Đục đẽo hoàn toàn từ các loại gỗ quý tự nhiên nguyên khối chọn lọc (gỗ hương, gỗ gụ, gỗ trắc). Thớ gỗ có độ bền cơ học cao, chống nứt nẻ, mối mọt và có mùi thơm tự nhiên.\n- Kỹ thuật chế tác: Phương pháp đục tay thủ công truyền thống kết hợp công nghệ làm mịn tinh xảo. Nghệ nhân chạm khắc sống động từng đường nét cơ bắp, cặp sừng oai nghiêm và nét hiền hòa của đôi trâu phong thủy.\n- Quản lý & Mã QR: Dán tem chứng nhận OCOP 4 sao chính thức của UBND TP. Hà Nội và tích hợp mã QR truy xuất nguồn gốc chống hàng giả.\n\nHướng dẫn bài trí & Bảo quản:\n- Bài trí tại phòng khách, bàn làm việc, sảnh doanh nghiệp để vượng tài giữ lộc.\n- Bảo quản nơi khô ráo, thoáng mát, tránh độ ẩm cao và ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785472060_AqBaCK93.jpg', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2022', 'Tác phẩm mỹ nghệ phong thủy \"Song ngưu sinh tài\" là kiệt tác điêu khắc gỗ thủ công độc đáo của Hộ kinh doanh Trần Văn Tân tại thôn Thạc Quả, xã Dục Tú, huyện Đông Anh, được UBND Thành phố Hà Nội trao chứng nhận OCOP 4 sao.\n\nTrong văn hóa phong thủy Á Đông, hình tượng \"Song ngưu\" (hai con trâu) tượng trưng cho sự no đủ, kiên trì, bền bỉ, sức khỏe dồi dào và thế đất \"vượng tài giữ lộc\". Khái niệm \"Sinh tài\" mang ý nghĩa thu hút may mắn, chiêu tài đón lộc dồi dào cho gia chủ. Bằng đôi bàn tay tài hoa của nghệ nhân xứ Đông Anh, thớ gỗ quý tự nhiên được chạm bong sinh động, mang lại giá trị thẩm mỹ mỹ nghệ nội thất cao cấp và ý nghĩa tâm linh phong thủy sâu sắc.', 'Nghệ nhân Trần Văn Tân (Thôn Thạc Quả, Xã Dục Tú, Huyện Đông Anh)', NULL, 'Song ngưu sinh tài là tác phẩm mỹ nghệ phong thủy độc đáo đạt chứng nhận OCOP 4 sao Cấp Thành phố Hà Nội của Hộ kinh doanh Trần Văn Tân, huyện Đông Anh. Được chế tác từ gỗ quý nguyên khối qua kỹ nghệ đục tay thủ công tinh xảo, đôi trâu tượng trưng cho sự bền bỉ, sức khỏe và thế đất vượng tài giữ lộc. Tác phẩm là điểm nhấn phong thủy sang trọng cho không gian phòng khách và bàn làm việc.', '[\"G\\u1ed7 qu\\u00fd t\\u1ef1 nhi\\u00ean nguy\\u00ean kh\\u1ed1i ch\\u1ecdn l\\u1ecdc (H\\u01b0\\u01a1ng\\/Tr\\u1eafc\\/G\\u1ee5)\",\"\\u0110\\u1ee5c tay th\\u1ee7 c\\u00f4ng chi ti\\u1ebft ch\\u1ea1m bong\",\"S\\u01a1n vecni \\u0111\\u00e1nh b\\u00f3ng t\\u1ef1 nhi\\u00ean\",\"M\\u00e3 QR tem ch\\u1ee9ng nh\\u1eadn OCOP 4 sao\"]', '[{\"year\":\"L\\u00e0ng ngh\\u1ec1\",\"event\":\"H\\u1ed9 kinh doanh Tr\\u1ea7n V\\u0103n T\\u00e2n ph\\u00e1t tri\\u1ec3n d\\u00f2ng s\\u1ea3n ph\\u1ea9m g\\u1ed7 m\\u1ef9 ngh\\u1ec7 phong th\\u1ee7y cao c\\u1ea5p t\\u1ea1i l\\u00e0ng ngh\\u1ec1 Th\\u1ea1c Qu\\u1ea3.\"},{\"year\":\"T\\u00e1c ph\\u1ea9m\",\"event\":\"Ho\\u00e0n th\\u00e0nh t\\u00e1c ph\\u1ea9m Song ng\\u01b0u sinh t\\u00e0i \\u0111i\\u00eau kh\\u1eafc th\\u1ee7 c\\u00f4ng nguy\\u00ean kh\\u1ed1i.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i theo Q\\u0110 s\\u1ed1 2008\\/Q\\u0110-UBND.\"},{\"year\":\"QR Truy xu\\u1ea5t\",\"event\":\"T\\u00edch h\\u1ee3p m\\u00e3 QR truy xu\\u1ea5t ngu\\u1ed3n g\\u1ed1c ch\\u1ed1ng h\\u00e0ng gi\\u1ea3 tr\\u00ean c\\u1ed5ng th\\u00f4ng tin H\\u00e0 N\\u1ed9i.\"}]'),
(6, 36, 189, 'Công ty TNHH Hoàng Chiến Thắng', 'Công ty TNHH Hoàng Chiến Thắng', NULL, 'MBBank', '0987654321', 'CÔNG TY TNHH HOÀNG CHIẾN THẮNG', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C3%94NG+TY+TNHH+HO%C3%80NG+CHI%E1%BA%BEN+TH%E1%BA%AENG&addInfo=TT+C%C3%B4ng+ty+TNHH+Ho%C3%A0ng+Chi%E1%BA%BFn+Th%E1%BA%AFng', 'Bánh gạo lứt', 30000.00, 'gói', 'Chủ thể sản xuất: Công ty TNHH Hoàng Chiến Thắng\nCăn cứ pháp lý & Địa chỉ: Thôn Đông Ngàn, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2022)\nThông tin thanh toán: 125349089 tại ngân hàng Acb\nKênh phân phối: Bán các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa\n\nCông ty TNHH Hoàng Chiến Thắng xin kính chào quý khách, cảm ơn quý khách đã sử dụng sản phẩm Bánh gạo lứt 300g!\n\n1. Hướng dẫn sử dụng & Bảo quản:\n- Sản phẩm ăn ngay không cần chế biến\n- Bảo quản ở nơi thoáng mát, sạch sẽ\n- Đậy kín miệng túi sau mỗi lần sử dụng\n\n2. Thành phần: Bột mỳ (95%), đường kính, nước sạch, dầu ăn, muối ăn, bột khai Ammonium Bicarbonate, trứng.\n\n3. Thời hạn sử dụng: 12 tháng kể từ ngày sản xuất.', 'https://media.xadonganh.com/ocop/1785469295_M3hWbB7n.png', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2022', 'Bánh gạo lứt 300g của Công ty TNHH Hoàng Chiến Thắng là sản phẩm bánh ngọt dinh dưỡng thơm ngon đặc trưng của Đông Anh. Sản phẩm kết hợp hài hòa nguồn bột mỳ chất lượng cao (95%), trứng tươi và bí quyết nướng gia truyền mang lại vị giòn rụm, béo nhẹ, phù hợp cho mọi lứa tuổi thưởng thức hàng ngày hoặc làm quà biếu.', 'Đội ngũ chế biến Công ty TNHH Hoàng Chiến Thắng', NULL, 'Bánh gạo lứt 300g là sản phẩm OCOP chất lượng cao của Công ty TNHH Hoàng Chiến Thắng, huyện Đông Anh. Với thành phần chính từ bột mỳ nguyên chất, trứng tươi và quy trình nướng hiện đại, bánh có hương vị giòn thơm dịu ngọt, vừa miệng. Sản phẩm ăn liền tiện lợi, có thời hạn sử dụng 12 tháng, thích hợp dùng làm quà biếu hoặc thưởng thức cùng trà nóng mỗi ngày.', '[\"B\\u1ed9t m\\u1ef3 (95%)\",\"\\u0110\\u01b0\\u1eddng k\\u00ednh\",\"Tr\\u1ee9ng t\\u01b0\\u01a1i\",\"N\\u01b0\\u1edbc s\\u1ea1ch\",\"D\\u1ea7u \\u0103n\",\"Mu\\u1ed1i \\u0103n\",\"B\\u1ed9t khai Ammonium Bicarbonate\"]', '[{\"year\":\"Ch\\u1ea5t l\\u01b0\\u1ee3ng\",\"event\":\"C\\u00f4ng ty TNHH Ho\\u00e0ng Chi\\u1ebfn Th\\u1eafng chu\\u1ea9n h\\u00f3a quy tr\\u00ecnh s\\u1ea3n xu\\u1ea5t b\\u00e1nh g\\u1ea1o l\\u1ee9t an to\\u00e0n v\\u1ec7 sinh th\\u1ef1c ph\\u1ea9m.\"},{\"year\":\"OCOP\",\"event\":\"S\\u1ea3n ph\\u1ea9m B\\u00e1nh g\\u1ea1o l\\u1ee9t 300g \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao UBND Huy\\u1ec7n \\u0110\\u00f4ng Anh.\"},{\"year\":\"L\\u01b0u th\\u00f4ng\",\"event\":\"Ph\\u00e2n ph\\u1ed1i r\\u1ed9ng kh\\u1eafp c\\u00e1c \\u0111\\u1ea1i l\\u00fd, si\\u00eau th\\u1ecb v\\u00e0 gian h\\u00e0ng n\\u00f4ng s\\u1ea3n \\u0110\\u00f4ng Anh.\"}]'),
(7, 36, 189, 'Công ty TNHH Hoàng Chiến Thắng', 'Công ty TNHH Hoàng Chiến Thắng', NULL, 'MBBank', '0987654321', 'CÔNG TY TNHH HOÀNG CHIẾN THẮNG', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C3%94NG+TY+TNHH+HO%C3%80NG+CHI%E1%BA%BEN+TH%E1%BA%AENG&addInfo=TT+C%C3%B4ng+ty+TNHH+Ho%C3%A0ng+Chi%E1%BA%BFn+Th%E1%BA%AFng', 'Bánh vừng vòng', 30000.00, 'gói', 'Chủ thể sản xuất: Công ty TNHH Hoàng Chiến Thắng\nCăn cứ pháp lý & Địa chỉ: Thôn Đông Ngàn, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 3 sao (Năm công nhận 2022)\nThông tin thanh toán: 125349089 tại ngân hàng Acb\nKênh phân phối: Bán các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa\n\nThông tin chi tiết về sản phẩm Bánh Vừng Vòng - Công ty TNHH Hoàng Chiến Thắng:\n\nBánh vừng vòng thơm mùi vừng, nở đều và có độ xốp giòn, vị ngọt vừa phải. Đây là loại bánh với nguyên liệu chỉ có đường sữa, bột mì, trứng gà và vừng rất đơn giản và rất an toàn. Bánh vừng vòng mang đậm hương vị dân gian, dễ thưởng thức, phù hợp với mọi lứa tuổi.\n\n1. Hướng dẫn sử dụng: Sử dụng ngay khi mở bao bì.\n\n2. Thành phần: Bột mì, lòng trắng trứng gà, đường bột, bơ, vừng.\n\n3. Bảo quản: Nơi khô ráo, thoáng mát.\n\n4. Hạn sử dụng: 18 tháng kể từ ngày sản xuất.', 'https://media.xadonganh.com/ocop/1785469773_h5iIK7BM.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2022', 'Bánh Vừng Vòng của Công ty TNHH Hoàng Chiến Thắng mang đậm hương vị dân gian truyền thống của vùng đất Đông Anh. Bánh được làm từ những nguyên liệu tự nhiên quen thuộc như bột mì, trứng gà tươi, bơ thơm và vừng rang. Khi thưởng thức, bánh có độ xốp giòn tan, vị ngọt thanh vừa phải quyện cùng hương thơm bùi bùi của hạt vừng rang vàng, mang lại ký ức ẩm thực quê hương đầm ấm.', 'Đội ngũ chế biến Công ty TNHH Hoàng Chiến Thắng', NULL, 'Bánh Vừng Vòng là sản phẩm OCOP đặc trưng của Công ty TNHH Hoàng Chiến Thắng, huyện Đông Anh. Bánh có hương vị thơm ngon bùi bùi của vừng rang, độ xốp giòn tan cùng vị ngọt dịu vừa phải. Được chế biến từ bột mì, lòng trắng trứng gà, bơ và đường bột tự nhiên, bánh vừng vòng mang đậm nét dân gian thanh nhã, phù hợp thưởng thức cùng trà ấm cho mọi lứa tuổi.', '[\"B\\u1ed9t m\\u00ec\",\"L\\u00f2ng tr\\u1eafng tr\\u1ee9ng g\\u00e0\",\"\\u0110\\u01b0\\u1eddng b\\u1ed9t\",\"B\\u01a1 th\\u01a1m\",\"H\\u1ea1t v\\u1eebng rang\"]', '[{\"year\":\"D\\u00e2n gian\",\"event\":\"B\\u00e1nh v\\u1eebng v\\u00f2ng l\\u00e0 m\\u00f3n b\\u00e1nh gi\\u00f2n x\\u1ed1p d\\u00e2n gian \\u0111\\u01b0\\u1ee3c ng\\u01b0\\u1eddi d\\u00e2n \\u0110\\u00f4ng Anh y\\u00eau th\\u00edch qua nhi\\u1ec1u th\\u1ebf h\\u1ec7.\"},{\"year\":\"Ch\\u1ebf bi\\u1ebfn\",\"event\":\"C\\u00f4ng ty TNHH Ho\\u00e0ng Chi\\u1ebfn Th\\u1eafng chu\\u1ea9n h\\u00f3a quy tr\\u00ecnh n\\u01b0\\u1edbng v\\u00e0 \\u0111\\u00f3ng g\\u00f3i \\u0111\\u1ea1t chu\\u1ea9n An To\\u00e0n V\\u1ec7 Sinh Th\\u1ef1c Ph\\u1ea9m.\"},{\"year\":\"OCOP\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao UBND Huy\\u1ec7n \\u0110\\u00f4ng Anh.\"}]'),
(8, 37, 190, 'Hợp tác xã dịch vụ nông nghiệp thôn Đoài', 'Hợp tác xã dịch vụ nông nghiệp thôn Đoài', NULL, 'MBBank', '0987654321', 'HỢP TÁC XÃ DỊCH VỤ NÔNG NGHIỆP THÔN ĐOÀI', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%A2P+T%C3%81C+X%C3%83+D%E1%BB%8ACH+V%E1%BB%A4+N%C3%94NG+NGHI%E1%BB%86P+TH%C3%94N+%C4%90O%C3%80I&addInfo=TT+H%E1%BB%A3p+t%C3%A1c+x%C3%A3+d%E1%BB%8Bch+v%E1%BB%A5+n%C3%B4ng+nghi%E1%BB%87p+th%C3%B4n+%C4%90o%C3%A0i', 'Tương Việt Hùng', 30000.00, 'đồng/lít', 'Chủ thể sản xuất: Hợp tác xã dịch vụ nông nghiệp thôn Đoài\nCăn cứ pháp lý & Địa chỉ: Thôn Đoài, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 3 sao (Năm công nhận 2022)\n\nThôn Đoài, xã Việt Hùng, huyện Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\n\nThông tin chi tiết về sản phẩm Tương Việt Hùng:\nKhác với cách làm tương ở Bần (Hưng Yên) hay Cự Đà (Hà Tây), người dân Dục Nội chỉ xay hạt đỗ tương vỡ đôi và ủ mốc tự nhiên, vì thế khi đạt đến độ \"chín\" Tương Việt Hùng không có vị chua, mùi thơm dịu.\n\nNước dùng làm tương phải là nước giếng được lấy vào buổi sáng sớm, việc chọn gạo nếp cái hoa vàng, đỗ tương hạt đều, mẩy và cách thức làm tương đúng quy trình: cứ 6kg gạo cộng 2kg đỗ cùng 1,5kg muối đi với 20 lít nước sẽ tạo ra một mẻ tương thơm ngon.\n\nThành phần: Gạo nếp cái hoa vàng, Đỗ tương hạt mẩy, Muối tinh, Nước giếng khơi sạch.\n\nSử dụng: Dùng trực tiếp làm nước chấm rau luộc, thịt luộc, cá kho hoặc gia vị nêm nếm món ăn gia đình.\n\nBảo quản: Đậy kín nắp sau khi dùng, bảo quản nơi khô ráo, thoáng mát.', 'https://media.xadonganh.com/ocop/1785468907_Qa52y12U.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2022', 'Tương Việt Hùng (Tương Dục Nội) là đặc sản ẩm thực truyền thống mang đậm hồn quê Đông Anh. Trong khi nhiều làng nghề khác chạy theo cơ chế thị trường, người làm tương ở Dục Nội vẫn giữ trọn màu sắc và hương vị tương truyền thống với các quy trình ngâm, ủ tự nhiên như xưa.\n\nXã Việt Hùng đã chú trọng công tác dồn điền đổi thửa và chuyển đổi cơ cấu cây trồng, xây dựng những cánh đồng trồng nếp cái hoa vàng chuyên biệt tại khu Ao Bạc, Bờ Hóp, Mạch Quế (thôn Trung), khu Ao Hóa (thôn Đoài)... tạo nguồn nguyên liệu dồi dào, chuẩn vị cho làng nghề.\n\nThời điểm làm tương thích hợp trong năm là từ tháng 5 đến tháng 10 âm lịch. Nếu đúng mùa hè thì 7 ngày được một mẻ, còn mùa đông phải 15 ngày mới hoàn thành 1 mẻ tương chín ngấu thơm ngon. Tương Việt Hùng đã trở thành món ăn quen thuộc trong căn bếp mỗi gia đình và là món quà biếu đặc sản quê hương khó phai.', 'Gia đình bà Hữu Thị Đông (Thôn Đoài) & Các hộ sản xuất làng nghề Tương Dục Nội', NULL, 'Tương Việt Hùng là đặc sản truyền thống nổi tiếng của xã Việt Hùng, huyện Đông Anh. Điểm đặc biệt của Tương Dục Nội là hạt đỗ tương chỉ xay vỡ đôi và ủ mốc tự nhiên, kết hợp cùng gạo nếp cái hoa vàng và nước giếng khơi tinh khiết. Tương chín ngấu có màu vàng sậm, vị ngọt đậm đà, mùi thơm dịu không bị chua. Đây là thức quà quê hương đậm đà tình nghĩa của vùng đất Đông Anh.', '[\"G\\u1ea1o n\\u1ebfp c\\u00e1i hoa v\\u00e0ng\",\"\\u0110\\u1ed7 t\\u01b0\\u01a1ng h\\u1ea1t m\\u1ea9y\",\"Mu\\u1ed1i tinh\",\"N\\u01b0\\u1edbc gi\\u1ebfng kh\\u01a1i s\\u1ea1ch\"]', '[{\"year\":\"\\u0110\\u1eb7c s\\u1ea3n\",\"event\":\"L\\u00e0ng ngh\\u1ec1 l\\u00e0m t\\u01b0\\u01a1ng truy\\u1ec1n th\\u1ed1ng D\\u1ee5c N\\u1ed9i h\\u00ecnh th\\u00e0nh v\\u00e0 \\u0111\\u01b0\\u1ee3c b\\u00e0 con g\\u00ecn gi\\u1eef qua nhi\\u1ec1u th\\u1ebf h\\u1ec7.\"},{\"year\":\"Quy ho\\u1ea1ch\",\"event\":\"X\\u00e3 Vi\\u1ec7t H\\u00f9ng quy ho\\u1ea1ch c\\u00e1nh \\u0111\\u1ed3ng n\\u1ebfp c\\u00e1i hoa v\\u00e0ng chuy\\u00ean bi\\u1ec7t t\\u1ea1i khu Ao B\\u1ea1c, B\\u1edd H\\u00f3p, M\\u1ea1ch Qu\\u1ebf, Ao H\\u00f3a.\"},{\"year\":\"Ch\\u1ee9ng nh\\u1eadn\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao UBND Huy\\u1ec7n \\u0110\\u00f4ng Anh theo Q\\u0110 s\\u1ed1 2008\\/Q\\u0110-UBND.\"}]'),
(9, 38, 191, 'HKD sản xuất và kinh doanh bánh ngọt Thùy Quyên', 'Hộ kinh doanh sản xuất và kinh doanh bánh ngọt Thúy Quyên', NULL, 'MBBank', '0987654321', 'HKD SẢN XUẤT VÀ KINH DOANH BÁNH NGỌT THÙY QUYÊN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HKD+S%E1%BA%A2N+XU%E1%BA%A4T+V%C3%80+KINH+DOANH+B%C3%81NH+NG%E1%BB%8CT+TH%C3%99Y+QUY%C3%8AN&addInfo=TT+HKD+s%E1%BA%A3n+xu%E1%BA%A5t+v%C3%A0+kinh+doanh+b%C3%A1nh+ng%E1%BB%8Dt+Th%C3%B9y+Quy%C3%AAn', 'Bánh xốp vừng', 22000.00, 'goi', 'Chủ thể sản xuất: Hộ kinh doanh sản xuất và kinh doanh bánh ngọt Thúy Quyên\nCăn cứ pháp lý & Địa chỉ: xóm Đông Ngàn, xã Đông Anh;  QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2023)\n\nĐịa chỉ xưởng: Thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh, TP. Hà Nội\nTiêu chuẩn: Đạt chứng nhận An Toàn Vệ Sinh Thực Phẩm, mã QR đồng bộ với Cổng truy xuất nguồn gốc nông sản Hà Nội.\n\nThông tin chi tiết sản phẩm Bánh xốp vừng Thúy Quyên:\n- Quy cách đóng gói: Gói 200g tịnh (Giá lẻ: 20.000đ - 24.000đ/gói; Giá nguyên thùng 30 gói 6kg: 285.000đ - 310.000đ/thùng).\n- Đặc tính cảm quan: Nướng lò điện khép kín chín vàng ươm. Cốt bánh bên trong nở rỗng xốp nhẹ, giòn tan khi chạm môi. Lớp vừng rang áo bên ngoài dày dặn béo ngậy, vị ngọt dịu thanh nhẹ không gắt đường.\n\nHướng dẫn sử dụng & Bảo quản:\n- Thưởng thức: Dùng trực tiếp ngay khi bóc gói. Rất ngon khi dùng kèm trà nóng hoặc cà phê trong các bữa ăn nhẹ, ăn xế.\n- Hạn sử dụng: 6 tháng kể từ ngày sản xuất.\n- Bảo quản: Nơi khô ráo thoáng mát. Bánh chưa dùng hết nên buộc chặt miệng túi để giữ độ giòn xốp.', 'https://media.xadonganh.com/ocop/1785468527_jGFjid1A.png', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:13:31', '2023', 'Bánh xốp vừng Thúy Quyên là món quà quê đậm đà hương vị truyền thống của Hộ kinh doanh Thúy Quyên tại thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh. Tác phẩm ẩm thực xuất sắc đạt chứng nhận OCOP 3 sao cấp Thành phố theo Quyết định số 560/QĐ-UBND.\n\nSinh ra từ làng quê Đông Anh giàu truyền thống làm nghề bánh ngọt, chiếc bánh xốp vừng Thúy Quyên kết tinh từ những nguyên liệu thuần khiết nhất: bột mì hảo hạng, trứng gà tươi, sữa đặc và những hạt vừng rang chín vàng thơm phức. Bí quyết gia truyền tạo nên sức hút khó cưỡng chính là tỷ lệ trứng sữa cao hòa quyện cùng kỹ thuật ủ bột nở tự nhiên tuyệt đối không dùng chất bảo quản. Khi thưởng thức, từng miếng bánh xốp nhẹ giòn tan như tan chảy trên đầu lưỡi, đọng lại vị béo bùi ngậy hương vừng thơm thanh khiết.', 'Chủ cơ sở Nguyễn Trọng Thăng & Nghệ nhân làm bánh Thúy Quyên (Đông Ngàn, Đông Hội, Đông Anh)', NULL, 'Bánh xốp vừng Thúy Quyên là đặc sản đạt chứng nhận OCOP 3 sao của Hộ kinh doanh Thúy Quyên, thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh. Được chế biến từ bột mì tuyển chọn, trứng gà tươi và áo lớp vừng rang béo ngậy nướng bằng lò điện khép kín, từng miếng bánh nở rỗng xốp nhẹ giòn tan mang hương vị bùi thơm thanh dịu khó quên.', '[\"B\\u1ed9t m\\u00ec h\\u1ea3o h\\u1ea1ng\",\"Tr\\u1ee9ng g\\u00e0 t\\u01b0\\u01a1i & S\\u1eefa \\u0111\\u1eb7c\",\"V\\u1eebng h\\u1ea1t t\\u00e1ch v\\u1ecf rang ch\\u00edn\",\"C\\u01a1m d\\u1eeba s\\u1ee3i s\\u1ea5y kh\\u00f4\",\"\\u0110\\u01b0\\u1eddng k\\u00ednh & D\\u1ea7u th\\u1ef1c v\\u1eadt\"]', '[{\"year\":\"L\\u00e0ng ngh\\u1ec1 B\\u00e1nh\",\"event\":\"C\\u01a1 s\\u1edf Th\\u00fay Quy\\u00ean duy tr\\u00ec v\\u00e0 ph\\u00e1t tri\\u1ec3n c\\u00f4ng th\\u1ee9c l\\u00e0m b\\u00e1nh x\\u1ed1p v\\u1eebng gia truy\\u1ec1n t\\u1ea1i \\u0110\\u00f4ng Ng\\u00e0n.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao theo Quy\\u1ebft \\u0111\\u1ecbnh s\\u1ed1 560\\/Q\\u0110-UBND.\"},{\"year\":\"M\\u00e3 QR Truy xu\\u1ea5t\",\"event\":\"\\u0110\\u1ed3ng b\\u1ed9 m\\u00e3 QR ch\\u1ee9ng nh\\u1eadn an to\\u00e0n th\\u1ef1c ph\\u1ea9m tr\\u00ean C\\u1ed5ng truy xu\\u1ea5t ngu\\u1ed3n g\\u1ed1c n\\u00f4ng s\\u1ea3n H\\u00e0 N\\u1ed9i.\"}]'),
(10, 38, 191, 'HKD sản xuất và kinh doanh bánh ngọt Thùy Quyên', 'Hộ kinh doanh sản xuất và kinh doanh bánh ngọt Thúy Quyên', NULL, 'MBBank', '0987654321', 'HKD SẢN XUẤT VÀ KINH DOANH BÁNH NGỌT THÙY QUYÊN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HKD+S%E1%BA%A2N+XU%E1%BA%A4T+V%C3%80+KINH+DOANH+B%C3%81NH+NG%E1%BB%8CT+TH%C3%99Y+QUY%C3%8AN&addInfo=TT+HKD+s%E1%BA%A3n+xu%E1%BA%A5t+v%C3%A0+kinh+doanh+b%C3%A1nh+ng%E1%BB%8Dt+Th%C3%B9y+Quy%C3%AAn', 'Bánh Sampa', 25000.00, 'goi', 'Chủ thể sản xuất: Hộ kinh doanh sản xuất và kinh doanh bánh ngọt Thúy Quyên\nCăn cứ pháp lý & Địa chỉ: xóm Đông Ngàn, xã Đông Anh;  QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2023)\n\nHộ kinh doanh Thúy Quyên xin kính chào quý khách!\r\nĐịa chỉ xưởng: Thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh, TP. Hà Nội\r\n\r\nThông tin chi tiết Bánh Sampa ít đường Thúy Quyên:\r\n- Quy cách đóng gói: Gói nilon thực phẩm kín khí bảo quản độ giòn thơm lâu.\r\n- Đặc điểm sản phẩm: Bánh Sampa truyền thống chế biến giảm lượng đường kính, giòn tan xốp mịn, vị bùi ngọt thanh dịu không gây ngấy đường.\r\n- Thành phần: Bột mì hảo hạng, trứng gà tươi chọn lọc, đường kính thanh, bơ thực vật, dầu ăn sạch.\r\n\r\nHướng dẫn sử dụng & Bảo quản:\r\n- Thưởng thức: Dùng ăn trực tiếp, rất hợp ăn nhẹ và uống cùng trà ấm hoặc cà phê.\r\n- Bảo quản: Nơi khô ráo thoáng mát, buộc chặt miệng túi sau khi mở để bánh không bị ỉu.', 'https://media.xadonganh.com/ocop/1785468597_YeMVMkCC.png', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:13:31', '2023', 'Bánh Sampa ít đường Thúy Quyên là dòng sản phẩm bánh ngọt truyền thống đạt chứng nhận OCOP 3 sao của Hộ kinh doanh Thúy Quyên tại thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh. Được chế biến từ nguồn bột mì cao cấp phối trộn cùng trứng gà tươi theo công thức gia truyền giảm ngọt độc đáo, bánh Sampa Thúy Quyên mang cốt bánh giòn rụm xốp nhẹ, hương thơm trứng sữa dịu dàng và vị ngọt thanh khiết phù hợp với xu hướng chăm sóc sức khỏe hiện đại.', 'Chủ cơ sở Nguyễn Trọng Thăng & Đội ngũ Thợ bánh Thúy Quyên (Đông Ngàn, Đông Hội, Đông Anh)', NULL, 'Bánh Sampa ít đường Thúy Quyên là sản phẩm đặc sản đạt chứng nhận OCOP 3 sao của Hộ kinh doanh Thúy Quyên, thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh. Với cốt bánh xốp giòn thanh ngọt giảm đường, bánh mang vị thơm ngậy trứng sữa tự nhiên, rất thích hợp thưởng thức cùng trà ấm gia đình.', '[\"B\\u1ed9t m\\u00ec cao c\\u1ea5p\",\"Tr\\u1ee9ng g\\u00e0 t\\u01b0\\u01a1i ngon\",\"\\u0110\\u01b0\\u1eddng k\\u00ednh thanh m\\u00e1t (\\u00edt \\u0111\\u01b0\\u1eddng)\",\"B\\u01a1 th\\u1ef1c v\\u1eadt & D\\u1ea7u \\u0103n\"]', '[{\"year\":\"Truy\\u1ec1n th\\u1ed1ng\",\"event\":\"C\\u01a1 s\\u1edf Th\\u00fay Quy\\u00ean duy tr\\u00ec v\\u00e0 c\\u1ea3i ti\\u1ebfn d\\u00f2ng B\\u00e1nh Sampa gi\\u1ea3m \\u0111\\u01b0\\u1eddng b\\u00f9i th\\u01a1m.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Quy\\u1ebft \\u0111\\u1ecbnh s\\u1ed1 560\\/Q\\u0110-UBND.\"}]'),
(11, 38, 191, 'HKD sản xuất và kinh doanh bánh ngọt Thùy Quyên', 'Hộ kinh doanh sản xuất và kinh doanh bánh ngọt Thúy Quyên', NULL, 'MBBank', '0987654321', 'HKD SẢN XUẤT VÀ KINH DOANH BÁNH NGỌT THÙY QUYÊN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HKD+S%E1%BA%A2N+XU%E1%BA%A4T+V%C3%80+KINH+DOANH+B%C3%81NH+NG%E1%BB%8CT+TH%C3%99Y+QUY%C3%8AN&addInfo=TT+HKD+s%E1%BA%A3n+xu%E1%BA%A5t+v%C3%A0+kinh+doanh+b%C3%A1nh+ng%E1%BB%8Dt+Th%C3%B9y+Quy%C3%AAn', 'Bánh trứng nhện', 25000.00, 'goi', 'Chủ thể sản xuất: Hộ kinh doanh sản xuất và kinh doanh bánh ngọt Thúy Quyên\nCăn cứ pháp lý & Địa chỉ: xóm Đông Ngàn, xã Đông Anh;  QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2023)\n\nĐịa chỉ xưởng: Thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh, TP. Hà Nội\nTiêu chuẩn: Tích hợp mã QR đồng bộ trên Cổng thông tin truy xuất nguồn gốc nông sản Hà Nội.\n\nThông tin chi tiết Bánh trứng nhện Thúy Quyên (Bánh nhện vừng):\n- Quy cách đóng gói: Đóng trong túi nhựa PP thực phẩm kín khí 200g - 250g (Giá bán lẻ: 22.000đ - 35.000đ/gói).\n- Kỹ thuật tạo hình độc đáo: Kỹ thuật đổ khuôn bột nướng tạo cốt bánh mỏng tròn dẹt với các đường vân rỗng xốp đan xen như sợi tơ nhện. Bề mặt bánh áo lớp hạt vừng trắng rang chín lốm đốm bắt mắt.\n- Trải nghiệm cảm quan: Nướng chín vàng ươm lò nhiệt khép kín. Giòn rụm cao, tan nhanh trong miệng, béo ngậy vị trứng sữa và thơm lừng mè rang, hậu vị ngọt thanh nhẹ.\n\nHướng dẫn sử dụng & Bảo quản:\n- Thưởng thức: Món quà quê giàu dinh dưỡng, rất hợp nhâm nhi cùng tách trà mạn búp mộc hoặc ăn nhẹ gia đình.\n- Bảo quản: Bánh kết cấu bọt khí rỗng xốp dễ hút ẩm. Khi bóc túi nếu dùng không hết bắt buộc buộc thật chặt miệng túi hoặc cho vào hộp/lọ thủy tinh đậy kín nắp.', 'https://media.xadonganh.com/ocop/1785468654_mAssxb7t.png', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:13:31', '2023', 'Bánh trứng nhện Thúy Quyên (còn gọi là Bánh nhện vừng hay Bánh quy đồng xu mè) là sản phẩm bánh nướng thủ công mang hình dáng độc đáo, sáng tạo của Hộ kinh doanh Thúy Quyên tại thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh. Tác phẩm xuất sắc đạt chứng nhận OCOP 3 sao Cấp Thành Phố theo Quyết định số 560/QĐ-UBND.\n\nTên gọi \"bánh trứng nhện\" xuất phát từ kỹ thuật đổ khuôn nướng bánh nghệ thuật với cốt bánh mỏng tròn dẹt có các đường vân rỗng xốp đan xen nhẹ nhàng như mạng tơ nhện. Lớp vừng trắng rang vàng ươm bám lốm đốm trên bề mặt vừa tạo nên vẻ đẹp mắt ngộ nghĩnh, vừa mang lại độ giòn rụm tan ngay nơi đầu lưỡi. Nhờ nguyên liệu trứng gà tươi phối trộn cùng sữa đặc và bột mì chọn lọc, mỗi chiếc bánh là sự hòa quyện tuyệt vời giữa vị béo ngậy thanh nhẹ và hương thơm nức của mè rang, trở thành món thức quà trà chiều yêu thích của mọi lứa tuổi.', 'Chủ cơ sở Nguyễn Trọng Thăng & Đội ngũ Thợ bánh Thúy Quyên (Đông Ngàn, Đông Hội, Đông Anh)', NULL, 'Bánh trứng nhện Thúy Quyên là sản phẩm đạt chứng nhận OCOP 3 sao Cấp Thành phố của Hộ kinh doanh Thúy Quyên, thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh. Với kỹ thuật đổ khuôn tạo hình đường vân rỗng xốp mỏng dẹt như mạng tơ nhện áo vừng rang vàng ươm, từng chiếc bánh giòn rụm tan nhanh trong miệng mang vị béo ngậy trứng sữa và hậu vị ngọt thanh nhẹ dịu dàng.', '[\"Tr\\u1ee9ng g\\u00e0 t\\u01b0\\u01a1i ngon\",\"B\\u1ed9t m\\u00ec h\\u1ea3o h\\u1ea1ng\",\"V\\u1eebng tr\\u1eafng h\\u1ea1t t\\u00e1ch v\\u1ecf rang ch\\u00edn\",\"S\\u1eefa \\u0111\\u1eb7c & \\u0110\\u01b0\\u1eddng k\\u00ednh\",\"D\\u1ea7u th\\u1ef1c v\\u1eadt tinh luy\\u1ec7n\"]', '[{\"year\":\"S\\u00e1ng t\\u1ea1o\",\"event\":\"C\\u01a1 s\\u1edf Th\\u00fay Quy\\u00ean ph\\u00e1t tri\\u1ec3n d\\u00f2ng B\\u00e1nh tr\\u1ee9ng nh\\u1ec7n v\\u1eebng t\\u1ea1o h\\u00ecnh t\\u01a1 nh\\u1ec7n \\u0111\\u1ed9c \\u0111\\u00e1o.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Quy\\u1ebft \\u0111\\u1ecbnh s\\u1ed1 560\\/Q\\u0110-UBND.\"},{\"year\":\"M\\u00e3 QR Truy xu\\u1ea5t\",\"event\":\"T\\u00edch h\\u1ee3p m\\u00e3 QR truy xu\\u1ea5t ngu\\u1ed3n g\\u1ed1c n\\u00f4ng s\\u1ea3n H\\u00e0 N\\u1ed9i ch\\u1ed1ng h\\u00e0ng gi\\u1ea3.\"}]'),
(12, 39, 192, 'Hộ kinh doanh Thạo Loan', 'Hộ kinh doanh Thạo Loan', '0943525525', 'MBBank', '0987654321', 'HỘ KINH DOANH THẠO LOAN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%98+KINH+DOANH+TH%E1%BA%A0O+LOAN&addInfo=TT+H%E1%BB%99+kinh+doanh+Th%E1%BA%A1o+Loan', 'Rượu gạo nếp Long Tửu', 65000.00, 'chai', 'Chủ thể sản xuất: Hộ kinh doanh Thạo Loan\r\nCăn cứ pháp lý & Địa chỉ: Thôn Xuân Canh, xã Đông Anh; QĐ số 560/QĐ-UBND ngày 27/1/2021\r\nPhân hạng OCOP: 3 sao (Năm công nhận 2023)\r\n\r\nĐịa chỉ cơ sở: Thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, TP. Hà Nội\r\nQuản lý: Dán tem OCOP chính thức và tích hợp mã QR đồng bộ trên Cổng thông tin truy xuất nguồn gốc nông sản Hà Nội.\r\n\r\nThông tin chi tiết Rượu gạo nếp Long Tửu:\r\n- Quy cách: Chai thủy tinh 500ml - 750ml thiết kế sang trọng lịch sự.\r\n- Kỹ thuật chế tác: Chưng cất men thuốc bắc 36 vị gia truyền kết hợp gạo nếp hoa vàng thuần khiết. Cốt rượu đi qua máy lọc hiện đại khử sạch Methanol và Aldehyde, ủ chín ngấu trong chum sành.\r\n- Cảm quan hương vị: Rượu trong vắt, hương thơm nồng nàn gạo nếp hoa vàng, uống êm dịu đằm thắm, không đau đầu khát nước.\r\n\r\nHướng dẫn sử dụng & Bảo quản:\r\n- Thưởng thức: Uống trực tiếp hoặc ướp lạnh trong các bữa tiệc gia đình, hội nghị, cưới hỏi.\r\n- Bảo quản: Nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785464823_db16J56q.jpg', '3 sao', '2026-07-27 03:31:12', '2026-08-01 04:39:35', '2023', 'Rượu gạo nếp Long Tửu là sản phẩm rượu truyền thống trứ danh của Hộ kinh doanh Thạo Loan tại thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, Hà Nội. Tác phẩm xuất sắc đạt chứng nhận OCOP 4 sao Cấp Thành Phố theo Quyết định số 7059/QĐ-UBND.\n\nĐược chưng cất theo phương pháp gia truyền ủ men thuốc bắc 36 vị kết hợp gạo nếp hoa vàng thuần khiết trên vùng đất bãi bồi Xuân Canh, giọt rượu nếp Long Tửu đi qua hệ thống máy lọc đa tầng khử sạch độc tố Aldehyde và Methanol trước khi ngâm ủ chín ngấu trong chum sành. Khi thưởng thức, rượu mang lại vị êm mượt nồng nàn, hậu vị ngọt đậm đà đằm thắm quyến rũ, tôn vinh nét đẹp văn hóa ẩm thực truyền thống Đông Anh.', 'Nghệ nhân Nguyễn Văn Thạo & Hộ kinh doanh Thạo Loan (Thôn Xuân Canh, Xã Xuân Canh, Đông Anh)', 'Sử dụng: Uống trực tiếp, rất ngon khi uống lạnh.\r\n\r\nDùng ngâm các loại hoa quả và thuốc quý\r\n\r\nLưu ý: không dùng cho người dưới 18 tuổi\r\n\r\nBảo quản nơi khô ráo thoáng mát', 'Rượu gạo nếp Long Tửu là sản phẩm đặc sản OCOP 4 sao của Hộ kinh doanh Thạo Loan, thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh. Được chưng cất từ gạo nếp hoa vàng ủ men thuốc bắc 36 vị và ngâm chum sành khử sạch độc tố, giọt rượu trong vắt mang hương thơm nồng nàn, vị êm dịu đằm thắm tuyệt đối an toàn cho sức khỏe.', '[\"G\\u1ea1o n\\u1ebfp c\\u00e1i hoa v\\u00e0ng thu\\u1ea7n khi\\u1ebft\",\"Men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb gia truy\\u1ec1n\",\"N\\u01b0\\u1edbc s\\u1ea1ch tinh khi\\u1ebft Xu\\u00e2n Canh\",\"\\u1ee6 chum s\\u00e0nh h\\u1ea1 th\\u1ed5 truy\\u1ec1n th\\u1ed1ng\"]', '[{\"year\":\"Men gia truy\\u1ec1n\",\"event\":\"Bao \\u0111\\u1eddi l\\u00e0m ngh\\u1ec1 ch\\u01b0ng c\\u1ea5t r\\u01b0\\u1ee3u n\\u1ebfp men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb t\\u1ea1i l\\u00e0ng Xu\\u00e2n Canh.\"},{\"year\":\"M\\u00e1y l\\u1ecdc \\u0111a t\\u1ea7ng\",\"event\":\"\\u0110\\u1ea7u t\\u01b0 h\\u1ec7 th\\u1ed1ng c\\u00f4ng ngh\\u1ec7 l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c t\\u1ed1 Aldehyde & Methanol an to\\u00e0n tuy\\u1ec7t \\u0111\\u1ed1i.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Q\\u0110 s\\u1ed1 7059\\/Q\\u0110-UBND.\"}]');
INSERT INTO `ocop_products` (`id`, `eatery_id`, `user_id`, `stall_name`, `seller_name`, `seller_phone`, `bank_name`, `bank_account`, `bank_holder`, `qr_code_path`, `name`, `price`, `unit`, `description`, `image_path`, `star_rating`, `created_at`, `updated_at`, `heritage_year`, `story`, `artisans`, `fun_fact`, `audio_narrative`, `ingredients`, `timeline`) VALUES
(13, 39, 192, 'Hộ kinh doanh Thạo Loan', 'Hộ kinh doanh Thạo Loan', NULL, 'MBBank', '0987654321', 'HỘ KINH DOANH THẠO LOAN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%98+KINH+DOANH+TH%E1%BA%A0O+LOAN&addInfo=TT+H%E1%BB%99+kinh+doanh+Th%E1%BA%A1o+Loan', 'Rượu dâu Long Tửu', 120000.00, 'chai', 'Chủ thể sản xuất: Hộ kinh doanh Thạo Loan\nCăn cứ pháp lý & Địa chỉ: Thôn Xuân Canh, xã Đông Anh; QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2023)\n\nĐịa chỉ cơ sở: Thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, TP. Hà Nội\nQuản lý: Dán tem OCOP 3 sao và mã QR truy xuất nguồn gốc đồng bộ trên Hệ thống dữ liệu nông sản Hà Nội.\n\nThông tin chi tiết Rượu dâu Long Tửu:\n- Quy cách: Chai thủy tinh cao cấp 500ml thiết kế sang trọng chỉn chu.\n- Nguyên liệu: Quả dâu tằm chín mọng tươi ngon kết hợp Rượu gạo nếp Long Tửu cốt đã qua công nghệ khử sạch hoàn toàn độc tố Aldehyde và Methanol.\n- Hương vị cảm quan: Rượu màu đỏ tím sẫm đặc trưng, nồng độ nhẹ êm dịu, vị ngọt thanh tự nhiên hòa quyện vị chua nhẹ dâu tằm, uống êm say không gây đau đầu.\n\nHướng dẫn thưởng thức & Bảo quản:\n- Thưởng thức: Ngon nhất khi uống lạnh (ướp đá hoặc để ngăn mát tủ lạnh 1-2 ly nhỏ trong bữa ăn). Thích hợp làm quà tặng đặc sản hoặc liên hoan gia đình.\n- Công dụng: Kích thích tiêu hóa ăn ngon miệng, bổ huyết dưỡng nhan làm hồng da mặt và giúp ngủ ngon giấc.\n- Bảo quản: Nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785467771_5XyLvBOr.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2023', 'Rượu dâu Long Tửu là dòng rượu trái cây đặc sản thượng hạng nằm trong bộ sản phẩm Rượu Long Tửu danh tiếng của Hộ kinh doanh Thạo Loan tại thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, Hà Nội. Tác phẩm xuất sắc đạt chứng nhận OCOP 3 sao Cấp Thành Phố theo Quyết định số 560/QĐ-UBND.\n\nĐược sản xuất hoàn toàn từ nguồn dâu tằm chín mọng thu hái tự nhiên kết hợp cùng cốt rượu gạo nếp Long Tửu gia truyền qua công nghệ khử sạch hoàn toàn độc tố Aldehyde và Methanol, Rượu dâu Long Tửu được ngâm ủ thủ công trong các chum sành truyền thống. Quá trình lên men tự nhiên giúp giọt rượu có sắc đỏ tím sẫm óng ả, hương vị êm dịu thanh ngọt thoảng chua nhẹ thanh khiết, không chỉ mang lại cảm giác dễ chịu khi thưởng thức mà còn có công dụng bổ huyết dưỡng nhan, hỗ trợ giấc ngủ ngon cho người tiêu dùng.', 'Nghệ nhân Nguyễn Văn Thạo & Hộ kinh doanh Thạo Loan (Thôn Xuân Canh, Xã Xuân Canh, Đông Anh)', NULL, 'Rượu dâu Long Tửu là sản phẩm rượu trái cây thượng hạng đạt chứng nhận OCOP 3 sao Cấp Thành phố của Hộ kinh doanh Thạo Loan, thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh. Kết hợp dâu tằm chín mọng với rượu nếp Long Tửu ngâm ủ chum sành gia truyền khử độc tố, giọt rượu màu đỏ tím sẫm mang vị ngọt thanh dịu mát, uống êm say ướp lạnh rất bổ huyết và tốt cho tiêu hóa.', '[\"Qu\\u1ea3 d\\u00e2u t\\u1eb1m t\\u01b0\\u01a1i ch\\u00edn m\\u1ecdng t\\u1ef1 nhi\\u00ean\",\"R\\u01b0\\u1ee3u n\\u1ebfp Long T\\u1eedu c\\u1ed1t tinh l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c t\\u1ed1\",\"Men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb gia truy\\u1ec1n\",\"M\\u1eadt d\\u00e2u l\\u00ean men t\\u1ef1 nhi\\u00ean\"]', '[{\"year\":\"Gia truy\\u1ec1n\",\"event\":\"H\\u1ed9 kinh doanh Th\\u1ea1o Loan gi\\u1eef g\\u00ecn v\\u00e0 ph\\u00e1t tri\\u1ec3n b\\u00ed quy\\u1ebft ng\\u00e2m \\u1ee7 r\\u01b0\\u1ee3u n\\u1ebfp v\\u00e0 r\\u01b0\\u1ee3u d\\u00e2u tr\\u00e1i c\\u00e2y gia truy\\u1ec1n.\"},{\"year\":\"Kh\\u1eed \\u0111\\u1ed9c t\\u1ed1\",\"event\":\"\\u0110\\u1ea7u t\\u01b0 h\\u1ec7 th\\u1ed1ng m\\u00e1y tinh l\\u1ecdc hi\\u1ec7n \\u0111\\u1ea1i kh\\u1eed s\\u1ea1ch \\u0111\\u1ed9c t\\u1ed1 Methanol v\\u00e0 Aldehyde trong r\\u01b0\\u1ee3u c\\u1ed1t.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"R\\u01b0\\u1ee3u d\\u00e2u Long T\\u1eedu \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Quy\\u1ebft \\u0111\\u1ecbnh s\\u1ed1 560\\/Q\\u0110-UBND.\"}]'),
(14, 40, 193, 'HTX dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa', 'Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa', NULL, 'MBBank', '0987654321', 'HTX DỊCH VỤ NÔNG NGHIỆP KINH DOANH TỔNG HỢP CỔ LOA', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HTX+D%E1%BB%8ACH+V%E1%BB%A4+N%C3%94NG+NGHI%E1%BB%86P+KINH+DOANH+T%E1%BB%94NG+H%E1%BB%A2P+C%E1%BB%94+LOA&addInfo=TT+HTX+d%E1%BB%8Bch+v%E1%BB%A5+n%C3%B4ng+nghi%E1%BB%87p+kinh+doanh+t%E1%BB%95ng+h%E1%BB%A3p+C%E1%BB%95+Loa', 'Hành lá', 15000.00, 'mó', 'Chủ thể sản xuất: Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa\nCăn cứ pháp lý & Địa chỉ: Trung tâm Cổ Loa, xã Cổ Loa, huyện Đông Anh, TP. Hà Nội; QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao Cấp Thành phố theo Quyết định số 560/QĐ-UBND của UBND Thành phố Hà Nội.\nQuản lý nguồn gốc: Quản lý bằng tem nhãn OCOP và tích hợp mã QR đồng bộ trên Cổng thông tin truy xuất nguồn gốc nông sản Hà Nội.\n\nThông tin chi tiết Hành lá Cổ Loa:\n- Quy cách: Đóng gói theo bó tiêu chuẩn sơ chế sạch sẽ, dán mác OCOP.\n- Thổ nhưỡng & Cảm quan: Gieo trồng trên phù sa vùng Cố đô Cổ Loa. Thân hành màu trắng chắc nịch, không bị xốp ruột. Lá hành non mượt màu xanh mềm, thon dài đều đặn.\n- Hương vị: Mùi thơm nồng đậm đặc trưng, hậu vị ngọt thanh dịu mát, không cay hăng quá mức.\n\nHướng dẫn sử dụng & Phân phối:\n- Ứng dụng: Gia vị quốc dân dậy mùi cho các món Phở Hà Nội, món canh hầm, mỡ hành, hành phi thượng hạng.\n- Phân phối: Cung ứng chuỗi siêu thị, thực phẩm sạch, bếp ăn công nghiệp và trường học tại Hà Nội & Đông Anh.\n- Bảo quản: Bảo quản nơi khô ráo thoáng mát hoặc bọc màng thực phẩm để ngăn mát tủ lạnh.', 'https://media.xadonganh.com/ocop/1785462183_4MExLMYb.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:26:07', '2024', 'Hành lá Cổ Loa là nông sản đặc sản đạt chứng nhận OCOP 3 sao Cấp Thành phố của Hợp tác xã Dịch vụ Nông nghiệp Kinh doanh tổng hợp Cổ Loa tại mảnh đất di sản Cố đô Cổ Loa lịch sử. Tác phẩm đạt chuẩn OCOP theo Quyết định số 560/QĐ-UBND của UBND Thành phố Hà Nội.\n\nĐược nuôi dưỡng trên vùng đất phù sa màu mỡ sông Hoàng Giang bởi sự đồng lòng canh tác hữu cơ của 1.353 thành viên HTX Cổ Loa, từng tép hành lá sở hữu củ trắng chắc nịch và sắc lá xanh mượt thon dài. Nguồn nước tưới tiêu thủy lợi khép kín cùng quy trình phân bón hoai mục giúp hành lá Cổ Loa giữ trọn hương vị thơm nồng đậm đà, hậu vị ngọt thanh dịu mát - là ngọn nguồn hương vị tạo nên linh hồn cho phở Hà Nội và ẩm thực truyền thống Việt.', 'Bà con nông dân HTX Dịch vụ Nông nghiệp Cổ Loa (1.353 thành viên)', NULL, 'Hành lá Cổ Loa là nông sản đặc sản OCOP 3 sao của HTX Dịch vụ Nông nghiệp Cổ Loa. Được gieo trồng trên phù sa sông Hoàng Giang bởi 1.353 hộ nông dân, tép hành củ trắng mượt mà lá xanh ngút ngàn mang hương vị thơm nồng tự nhiên, làm dậy mùi các món Phở Hà Nội và ẩm thực gia đình Việt.', '[\"100% H\\u00e0nh l\\u00e1 t\\u01b0\\u01a1i gieo tr\\u1ed3ng t\\u1ea1i C\\u1ed1 \\u0111\\u00f4 C\\u1ed5 Loa (VietGAP)\"]', '[{\"year\":\"Tr\\u1ed3ng h\\u1eefu c\\u01a1\",\"event\":\"\\u00c1p d\\u1ee5ng canh t\\u00e1c sinh h\\u1ecdc VietGAP kh\\u00e9p k\\u00edn tr\\u00ean \\u0111\\u1ed3ng b\\u00e3i C\\u1ed5 Loa.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Q\\u0110 s\\u1ed1 560\\/Q\\u0110-UBND.\"}]'),
(15, 40, 193, 'HTX dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa', 'Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa', NULL, 'MBBank', '0987654321', 'HTX DỊCH VỤ NÔNG NGHIỆP KINH DOANH TỔNG HỢP CỔ LOA', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HTX+D%E1%BB%8ACH+V%E1%BB%A4+N%C3%94NG+NGHI%E1%BB%86P+KINH+DOANH+T%E1%BB%94NG+H%E1%BB%A2P+C%E1%BB%94+LOA&addInfo=TT+HTX+d%E1%BB%8Bch+v%E1%BB%A5+n%C3%B4ng+nghi%E1%BB%87p+kinh+doanh+t%E1%BB%95ng+h%E1%BB%A3p+C%E1%BB%95+Loa', 'Khoai tây', 25000.00, 'kg', 'Chủ thể sản xuất: Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa\nCăn cứ pháp lý & Địa chỉ: QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2024)\n\nĐịa chỉ: Thôn Cổ Loa, xã Cổ Loa, huyện Đông Anh, TP. Hà Nội\n\nThông tin chi tiết Khoai tây Cổ Loa:\n- Nông sản an toàn gieo trồng trên vùng đất bãi phù sa màu mỡ sông Hoàng Giang Cổ Loa.\n- Quy trình chăm sóc sinh học theo tiêu chuẩn VietGAP, không sử dụng hóa chất bảo vệ thực phẩm độc hại.\n- Tươi ngon đậm đà giàu dinh dưỡng tự nhiên.', 'https://media.xadonganh.com/ocop/1785462204_iZJj4pEQ.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:13:31', '2024', 'Khoai tây Cổ Loa là sản phẩm nông sản sạch đạt chứng nhận OCOP của HTX dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa, mảnh đất di sản Cố đô Cổ Loa lịch sử. Được nuôi dưỡng bởi phù sa màu mỡ và bàn tay chăm sóc cần cù của bà con nông dân, sản phẩm đảm bảo tiêu chuẩn an toàn VietGAP tươi ngon giàu dinh dưỡng.', 'Bà con nông dân HTX Nông nghiệp Cổ Loa (Thôn Cổ Loa, Đông Anh)', NULL, 'Khoai tây Cổ Loa là nông sản sạch đạt chứng nhận OCOP của HTX nông nghiệp Cổ Loa, huyện Đông Anh. Được gieo trồng theo chuẩn VietGAP an toàn sinh học trên vùng đất bãi Cổ Loa, sản phẩm mang lại nguồn thực phẩm tươi ngon giàu dinh dưỡng cho mọi gia đình.', '[\"100% N\\u00f4ng s\\u1ea3n t\\u01b0\\u01a1i s\\u1ea1ch gieo tr\\u1ed3ng t\\u1ea1i v\\u00f9ng di s\\u1ea3n C\\u1ed5 Loa\"]', '[{\"year\":\"VietGAP\",\"event\":\"\\u1ee8ng d\\u1ee5ng m\\u00f4 h\\u00ecnh tr\\u1ed3ng n\\u00f4ng s\\u1ea3n an to\\u00e0n VietGAP t\\u1ea1i di s\\u1ea3n C\\u1ed5 Loa.\"},{\"year\":\"OCOP C\\u1ea5p TP\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"}]'),
(16, 42, 194, 'Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Dục Tú', 'Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Dục Tú', NULL, 'MBBank', '0987654321', 'HỢP TÁC XÃ DỊCH VỤ NÔNG NGHIỆP KINH DOANH TỔNG HỢP DỤC TÚ', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%A2P+T%C3%81C+X%C3%83+D%E1%BB%8ACH+V%E1%BB%A4+N%C3%94NG+NGHI%E1%BB%86P+KINH+DOANH+T%E1%BB%94NG+H%E1%BB%A2P+D%E1%BB%A4C+T%C3%9A&addInfo=TT+H%E1%BB%A3p+t%C3%A1c+x%C3%A3+d%E1%BB%8Bch+v%E1%BB%A5+n%C3%B4ng+nghi%E1%BB%87p+kinh+doanh+t%E1%BB%95ng+h%E1%BB%A3p+D%E1%BB%A5c+T%C3%BA', 'Gạo nếp cái hoa vàng', 35000.00, 'kg', 'Chủ thể sản xuất: Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Dục Tú\nCăn cứ pháp lý & Địa chỉ: Thôn Dục Tú, xã Đông Anh; QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2024)\n\nĐịa chỉ: Thôn Dục Tú, xã Dục Tú, huyện Đông Anh, TP. Hà Nội\n\nThông tin chi tiết Gạo nếp cái hoa vàng Dục Tú:\n- Đặc điểm: Hạt gạo tròn căng mọng, màu trắng đục, khi đồ xôi hoặc gói bánh chưng bánh tét dẻo thơm nức nở, hạt gạo không bị nát hay cứng khi để nguội.\n- Quy trình: Trồng trên vùng đồng đất bãi bồi ven sông Dục Tú theo quy chuẩn VietGAP an toàn sinh học.\n- Bảo quản: Nơi khô ráo thoáng mát, đậy kín nắp thùng gạo tránh ẩm mốc.', 'https://media.xadonganh.com/ocop/1785460750_ax8SFhGS.png', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:13:31', '2024', 'Gạo nếp cái hoa vàng Dục Tú là sản phẩm nông sản OCOP 4 sao tiêu biểu của Hợp tác xã dịch vụ nông nghiệp Dục Tú, huyện Đông Anh. Được gieo trồng trên vùng đồng đất phù sa màu mỡ Dục Tú, hạt gạo nếp mang hương vị dẻo thơm đặc trưng ngát hương đồng quê, là nguyên liệu vàng cho các món xôi gấc, bánh chưng truyền thống.', 'Bà con nông dân HTX nông nghiệp Dục Tú (Thôn Dục Tú, Đông Anh)', NULL, 'Gạo nếp cái hoa vàng Dục Tú là đặc sản OCOP 4 sao của HTX nông nghiệp Dục Tú, huyện Đông Anh. Hạt gạo tròn căng dẻo thơm nức nở, mang trọn hương vị phù sa đồng quê Đông Anh.', '[\"100% G\\u1ea1o n\\u1ebfp c\\u00e1i hoa v\\u00e0ng D\\u1ee5c T\\u00fa thu\\u1ea7n ch\\u1ee7ng ch\\u1ecdn l\\u1ecdc\"]', '[{\"year\":\"Gi\\u1ed1ng thu\\u1ea7n ch\\u1ee7ng\",\"event\":\"Quy ho\\u1ea1ch v\\u00f9ng tr\\u1ed3ng l\\u00faa n\\u1ebfp c\\u00e1i hoa v\\u00e0ng thu\\u1ea7n ch\\u1ee7ng t\\u1ea1i D\\u1ee5c T\\u00fa.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"}]'),
(17, 36, 189, 'Công ty TNHH Hoàng Chiến Thắng', 'Công ty TNHH Hoàng Chiến Thắng', NULL, 'MBBank', '0987654321', 'CÔNG TY TNHH HOÀNG CHIẾN THẮNG', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C3%94NG+TY+TNHH+HO%C3%80NG+CHI%E1%BA%BEN+TH%E1%BA%AENG&addInfo=TT+C%C3%B4ng+ty+TNHH+Ho%C3%A0ng+Chi%E1%BA%BFn+Th%E1%BA%AFng', 'Bánh Sampa', 30000.00, 'gói', 'Chủ thể sản xuất: Công ty TNHH Hoàng Chiến Thắng\nCăn cứ pháp lý & Địa chỉ: Thôn Đông Ngàn, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2024)\nThông tin thanh toán: 125349089 tại ngân hàng Acb\nKênh phân phối: Bán các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa\n\nCông ty TNHH Hoàng Chiến Thắng xin kính chào quý khách, cảm ơn quý khách đã sử dụng sản phẩm Bánh Sampa 4 sao!\n\n1. Hướng dẫn sử dụng & Bảo quản:\n- Sản phẩm ăn ngay không cần chế biến\n- Bảo quản ở nơi thoáng mát, sạch sẽ\n- Đậy kín miệng túi sau mỗi lần sử dụng\n\n2. Thành phần: Bột mỳ (95%), đường kính, nước sạch, dầu ăn, muối ăn, bột khai Ammonium Bicarbonate, trứng tươi.\n\n3. Thời hạn sử dụng: 12 tháng kể từ ngày sản xuất.\n\n4. Phân phối: Bán tại các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa.', 'https://media.xadonganh.com/ocop/1785469991_xjxtRh60.png', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2024', 'Bánh Sampa 4 sao là dòng sản phẩm cao cấp của Công ty TNHH Hoàng Chiến Thắng. Bánh được chọn lọc từ nguồn nguyên liệu thượng hạng, bột mỳ đạt chuẩn 95% kết hợp cùng trứng tươi và bơ cao cấp. Với công thức nướng giòn xốp đặc biệt và chứng nhận OCOP 4 sao Cấp Quốc Gia, bánh mang lại vị thơm béo đậm đà, phù hợp làm quà tặng di sản sang trọng.', NULL, NULL, NULL, NULL, NULL),
(18, 36, 189, 'Công ty TNHH Hoàng Chiến Thắng', 'Công ty TNHH Hoàng Chiến Thắng', NULL, 'MBBank', '0987654321', 'CÔNG TY TNHH HOÀNG CHIẾN THẮNG', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C3%94NG+TY+TNHH+HO%C3%80NG+CHI%E1%BA%BEN+TH%E1%BA%AENG&addInfo=TT+C%C3%B4ng+ty+TNHH+Ho%C3%A0ng+Chi%E1%BA%BFn+Th%E1%BA%AFng', 'Bánh nhện vừng', 30000.00, 'gói', 'Chủ thể sản xuất: Công ty TNHH Hoàng Chiến Thắng\nCăn cứ pháp lý & Địa chỉ: Thôn Đông Ngàn, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2024)\nThông tin thanh toán: 125349089 tại ngân hàng Acb\nKênh phân phối: Bán các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa\n\nCông ty TNHH Hoàng Chiến Thắng xin kính chào quý khách, cảm ơn quý khách đã sử dụng sản phẩm Bánh Nhện Vừng!\n\nThông tin chi tiết sản phẩm Bánh Nhện Vừng:\n- Bánh xốp vừng thơm ngon giòn rụm kết hợp dừa nạo và hương vani tự nhiên.\n\n1. Hướng dẫn sử dụng & Đóng gói:\n- Sản phẩm ăn ngay không cần chế biến. Đẩy kín bao bì sau khi mở.\n- Quy cách bao bì: Túi PE, túi giấy, hộp nhựa chuyên dùng đảm bảo an toàn vệ sinh thực phẩm theo quy định của Bộ Y Tế.\n\n2. Thành phần: Bột mỳ, đường kính, trứng, dừa, nước sạch, dầu ăn, muối ăn, bột khai Ammonium Bicarbonate, hương vani.\n\n3. Công nghệ sản xuất: Dây chuyền hiện đại gồm máy trộn bột, máy đánh trứng, máy chít, lò nướng, máy hàn và máy in date đạt chuẩn ATTP.', 'https://media.xadonganh.com/ocop/1785470179_HIOfAaeb.png', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2024', 'Bánh Nhện Vừng của Công ty TNHH Hoàng Chiến Thắng là món bánh ngọt truyền thống độc đáo với tạo hình đan lưới giòn xốp đặc trưng. Bánh là sự kết hợp hòa quyện giữa bột mỳ tuyển chọn, trứng tươi, dừa nạo sấy thơm bùi và hương vani dịu ngọt. Được nướng trên dây chuyền hiện đại đảm bảo tiêu chuẩn an toàn vệ sinh thực phẩm của Bộ Y Tế, Bánh Nhện Vừng mang lại trải nghiệm ẩm thực giòn rụm béo ngậy cho mọi lứa tuổi.', 'Đội ngũ chế biến Công ty TNHH Hoàng Chiến Thắng', NULL, 'Bánh Nhện Vừng là sản phẩm OCOP 4 sao nổi tiếng của Công ty TNHH Hoàng Chiến Thắng, huyện Đông Anh. Bánh gây ấn tượng bởi hình dáng đan lưới giòn xốp, hương thơm ngát của dừa tươi và vani tự nhiên. Được sản xuất trên dây chuyền lò nướng hiện đại và đóng gói bao bì đạt chuẩn an toàn vệ sinh thực phẩm của Bộ Y Tế, Bánh Nhện Vừng là món quà quê hương giòn rụm béo thơm cho mọi gia đình.', '[\"B\\u1ed9t m\\u1ef3 tuy\\u1ec3n ch\\u1ecdn\",\"\\u0110\\u01b0\\u1eddng k\\u00ednh\",\"Tr\\u1ee9ng t\\u01b0\\u01a1i\",\"D\\u1eeba s\\u1ea5y th\\u01a1m\",\"N\\u01b0\\u1edbc s\\u1ea1ch\",\"D\\u1ea7u \\u0103n\",\"Mu\\u1ed1i \\u0103n\",\"B\\u1ed9t khai Ammonium Bicarbonate\",\"H\\u01b0\\u01a1ng vani\"]', '[{\"year\":\"C\\u00f4ng ngh\\u1ec7\",\"event\":\"C\\u00f4ng ty TNHH Ho\\u00e0ng Chi\\u1ebfn Th\\u1eafng \\u0111\\u1ea7u t\\u01b0 d\\u00e2y chuy\\u1ec1n m\\u00e1y tr\\u1ed9n, l\\u00f2 n\\u01b0\\u1edbng hi\\u1ec7n \\u0111\\u1ea1i \\u0111\\u1ea1t chu\\u1ea9n B\\u1ed9 Y T\\u1ebf.\"},{\"year\":\"Ch\\u1ee9ng nh\\u1eadn\",\"event\":\"S\\u1ea3n ph\\u1ea9m B\\u00e1nh Nh\\u1ec7n V\\u1eebng \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao UBND Huy\\u1ec7n \\u0110\\u00f4ng Anh.\"},{\"year\":\"Bao b\\u00ec\",\"event\":\"Chu\\u1ea9n h\\u00f3a bao b\\u00ec t\\u00fai PE, t\\u00fai gi\\u1ea5y v\\u00e0 h\\u1ed9p nh\\u1ef1a b\\u1ea3o v\\u1ec7 an to\\u00e0n v\\u1ec7 sinh th\\u1ef1c ph\\u1ea9m.\"}]'),
(19, 36, 189, 'Công ty TNHH Hoàng Chiến Thắng', 'Công ty TNHH Hoàng Chiến Thắng', NULL, 'MBBank', '0987654321', 'CÔNG TY TNHH HOÀNG CHIẾN THẮNG', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C3%94NG+TY+TNHH+HO%C3%80NG+CHI%E1%BA%BEN+TH%E1%BA%AENG&addInfo=TT+C%C3%B4ng+ty+TNHH+Ho%C3%A0ng+Chi%E1%BA%BFn+Th%E1%BA%AFng', 'Bánh Vòng Dừa (Coconut Biscuit)', 30000.00, 'chai', 'Chủ thể sản xuất: Công ty TNHH Hoàng Chiến Thắng\nCăn cứ pháp lý & Địa chỉ: Thôn Đông Ngàn, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 4 sao (Năm công nhận 2024)\nThông tin thanh toán: 125349089 tại ngân hàng Acb\nKênh phân phối: Bán các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa\n\nĐịa chỉ cơ sở: Thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, TP. Hà Nội\nQuản lý: Tích hợp mã QR kiểm soát truy xuất nguồn gốc trên Hệ thống nông sản Hà Nội.\n\nThông tin chi tiết Rượu Bạch cúc Long Tửu (Rượu Hoa cúc Long Tửu):\n- Quy cách: Chai thủy tinh cao cấp 500ml nhãn mác mang đậm dấu ấn làng nghề truyền thống Đông Anh.\n- Nguyên liệu: Hoa bạch cúc (hoa cúc trắng thảo dược) sấy khô nguyên bông tinh khiết kết hợp Rượu gạo nếp Long Tửu cốt qua máy lọc đa tầng khử sạch độc tố Methanol và Aldehyde.\n- Hương vị cảm quan: Sắc vàng nhạt óng ả trong vắt. Hương thơm thảo mộc tự nhiên dịu nhẹ thanh mát hoa cúc. Nồng độ êm mượt (29% - 32% Vol), vị cay nhẹ hòa quyện hậu vị ngọt thanh sâu lắng, uống không đau đầu mệt mỏi.\n\nHướng dẫn thưởng thức & Bảo quản:\n- Thưởng thức ngon nhất: Ướp lạnh sâu trong ngăn mát tủ lạnh, thích hợp làm đồ khai vị thanh lịch (1 - 2 chén nhỏ trong bữa ăn).\n- Công dụng: Thanh nhiệt giải độc mát gan sáng mắt, giảm đau đầu an thần giúp giấc ngủ sâu, kích thích tiêu hóa ăn ngon miệng.\n- Bảo quản: Nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785470818_wwouY8H3.png', '4 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2024', 'Rượu Bạch cúc Long Tửu (còn gọi là Rượu Hoa cúc Long Tửu) là dòng sản phẩm rượu hoa truyền thống đặc sắc nằm trong bộ ba Rượu Long Tửu danh tiếng đạt chứng nhận OCOP 3 sao của Hộ kinh doanh Thạo Loan tại thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, Hà Nội.\n\nTác phẩm độc đáo này kết hợp tinh tế giữa những bông hoa bạch cúc trắng sấy khô nguyên bông tinh khiết và dòng Rượu gạo nếp Long Tửu cốt chưng cất men thuốc bắc 36 vị. Cốt rượu được tinh lọc qua hệ thống máy lọc hiện đại nhằm triệt tiêu hoàn toàn độc tố Methanol và Aldehyde. Trải qua quá trình ngâm ủ kỹ lưỡng dài ngày trong chum sành, từng giọt rượu đọng lại sắc vàng nhạt óng ả trong vắt, phảng phất hương thơm thảo mộc tự nhiên ngát hương hoa cúc. Khi thưởng thức, nồng độ êm mượt cùng vị ngọt thanh sâu lắng mang lại cảm giác an thần, giải độc mát gan và thư thái tinh thần tuyệt đối.', 'Nghệ nhân Nguyễn Văn Thạo & Hộ kinh doanh Thạo Loan (Thôn Xuân Canh, Xã Xuân Canh, Đông Anh)', NULL, 'Rượu Bạch cúc Long Tửu là sản phẩm rượu hoa thảo mộc thượng hạng đạt chứng nhận OCOP 3 sao Cấp Thành phố của Hộ kinh doanh Thạo Loan, thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh. Được chế tác từ những bông cúc trắng tinh khiết ngâm ủ trong rượu nếp gia truyền lọc sạch độc tố, giọt rượu sắc vàng nhạt óng ả mang hương thơm thảo mộc thanh dịu, vị êm mượt thanh ngọt giúp mát gan, sáng mắt và an thần ngon giấc.', '[\"Hoa b\\u1ea1ch c\\u00fac tr\\u1eafng s\\u1ea5y kh\\u00f4 nguy\\u00ean b\\u00f4ng\",\"R\\u01b0\\u1ee3u n\\u1ebfp Long T\\u1eedu c\\u1ed1t tinh l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c t\\u1ed1\",\"Men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb gia truy\\u1ec1n\",\"Tinh ch\\u1ea5t th\\u1ea3o m\\u1ed9c hoa c\\u00fac t\\u1ef1 nhi\\u00ean\"]', '[{\"year\":\"R\\u01b0\\u1ee3u Hoa Th\\u1ea3o D\\u01b0\\u1ee3c\",\"event\":\"H\\u1ed9 kinh doanh Th\\u1ea1o Loan ng\\u00e2m \\u1ee7 th\\u00e0nh c\\u00f4ng d\\u00f2ng R\\u01b0\\u1ee3u B\\u1ea1ch c\\u00fac t\\u1eeb hoa c\\u00fac tr\\u1eafng.\"},{\"year\":\"Tinh l\\u1ecdc \\u0111a t\\u1ea7ng\",\"event\":\"\\u0110\\u1ea7u t\\u01b0 m\\u00e1y l\\u1ecdc \\u0111a t\\u1ea7ng kh\\u1eed s\\u1ea1ch \\u0111\\u1ed9c t\\u1ed1 Methanol v\\u00e0 Aldehyde b\\u1ea3o v\\u1ec7 s\\u1ee9c kh\\u1ecfe.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"R\\u01b0\\u1ee3u B\\u1ea1ch c\\u00fac Long T\\u1eedu \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"}]'),
(20, 39, 192, 'Hộ kinh doanh Thạo Loan', 'Hộ kinh doanh Thạo Loan', NULL, 'MBBank', '0987654321', 'HỘ KINH DOANH THẠO LOAN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%98+KINH+DOANH+TH%E1%BA%A0O+LOAN&addInfo=TT+H%E1%BB%99+kinh+doanh+Th%E1%BA%A1o+Loan', 'Rượu mơ Long Tửu', 120000.00, 'chai', 'Chủ thể sản xuất: Hộ kinh doanh Thạo Loan\nCăn cứ pháp lý & Địa chỉ: Thôn Xuân Canh, xã Đông Anh; QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2024)\n\nĐịa chỉ cơ sở: Thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, TP. Hà Nội\nQuản lý: Đầy đủ tem nhãn OCOP 3 sao và mã QR truy xuất nguồn gốc nông sản Hà Nội.\n\nThông tin chi tiết Rượu mơ Long Tửu:\n- Quy cách: Chai thủy tinh 500ml thiết kế trang nhã, lịch sự.\n- Nguyên liệu: Quả mơ má đào / mơ lông chín vàng tươi ngâm ủ cùng Rượu gạo nếp Long Tửu cốt qua hệ thống máy lọc khử độc tố Aldehyde và Methanol hiện đại.\n- Cảm quan hương vị: Sắc vàng hổ phách trong vắt óng ả. Hương thơm thanh mát quả mơ chín, nồng độ nhẹ nhàng vị chua thanh hòa quyện hậu vị ngọt dịu, hoàn toàn không gây đau đầu khát nước.\n\nHướng dẫn thưởng thức & Bảo quản:\n- Thưởng thức ngon nhất: Ướp lạnh sâu hoặc uống kèm đá viên mùa hè như cocktail giải nhiệt (1 - 2 ly nhỏ trong bữa ăn).\n- Công dụng: Kích thích tiêu hóa ăn ngon miệng, thư giãn an thần hỗ trợ giấc ngủ sâu.\n- Bảo quản: Nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785467851_tweFe20e.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2024', 'Rượu mơ Long Tửu là một trong những tác phẩm rượu trái cây nổi bật nằm trong bộ sản phẩm Rượu Long Tửu truyền thống của Hộ kinh doanh Thạo Loan tại thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh. Sản phẩm xuất sắc đạt chứng nhận OCOP 3 sao Cấp Thành Phố theo Quyết định số 560/QĐ-UBND.\n\nSản phẩm là sự giao thoa hoàn hảo giữa những quả mơ má đào, mơ lông chín vàng tươi căng mọng ngát hương và dòng Rượu gạo nếp Long Tửu cốt tinh khiết đã qua hệ thống khử sạch độc tố. Được ngâm ủ dài ngày trong các chum sành truyền thống, quả mơ tiết trọn vị chua thanh và chất ngọt tự nhiên vào cốt rượu, tạo nên giọt rượu màu vàng hổ phách óng ả sang trọng. Vị êm mượt nồng độ vừa phải cùng khả năng an thần giải tỏa stress khiến Rượu mơ Long Tửu trở thành lựa chọn quà biếu và thức uống sang trọng hàng đầu cho mọi dịp tiệc mừng.', 'Nghệ nhân Nguyễn Văn Thạo & Hộ kinh doanh Thạo Loan (Thôn Xuân Canh, Xã Xuân Canh, Đông Anh)', NULL, 'Rượu mơ Long Tửu là sản phẩm đặc sản đạt chứng nhận OCOP 3 sao Cấp Thành phố của Hộ kinh doanh Thạo Loan, thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh. Được chế tác từ những quả mơ chín vàng tươi căng mọng ngâm ủ chum sành với rượu nếp gia truyền tinh lọc độc tố, giọt rượu màu vàng hổ phách óng ả có nồng độ nhẹ êm mượt, vị chua thanh ngọt dịu giúp kích thích tiêu hóa và an thần ngon giấc.', '[\"Qu\\u1ea3 m\\u01a1 m\\u00e1 \\u0111\\u00e0o \\/ m\\u01a1 l\\u00f4ng t\\u01b0\\u01a1i ch\\u00edn v\\u00e0ng\",\"R\\u01b0\\u1ee3u n\\u1ebfp Long T\\u1eedu c\\u1ed1t tinh l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c t\\u1ed1\",\"Men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb gia truy\\u1ec1n\",\"M\\u1eadt m\\u01a1 l\\u00ean men t\\u1ef1 nhi\\u00ean\"]', '[{\"year\":\"Gia truy\\u1ec1n\",\"event\":\"H\\u1ed9 kinh doanh Th\\u1ea1o Loan ph\\u00e1t tri\\u1ec3n d\\u00f2ng s\\u1ea3n ph\\u1ea9m r\\u01b0\\u1ee3u m\\u01a1 tr\\u00e1i c\\u00e2y ng\\u00e2m chum s\\u00e0nh c\\u1ed5 truy\\u1ec1n.\"},{\"year\":\"M\\u00e1y l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c\",\"event\":\"\\u1ee8ng d\\u1ee5ng h\\u1ec7 th\\u1ed1ng l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c t\\u1ed1 Methanol & Aldehyde b\\u1ea3o v\\u1ec7 s\\u1ee9c kh\\u1ecfe ng\\u01b0\\u1eddi d\\u00f9ng.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"R\\u01b0\\u1ee3u m\\u01a1 Long T\\u1eedu \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Quy\\u1ebft \\u0111\\u1ecbnh s\\u1ed1 560\\/Q\\u0110-UBND.\"}]'),
(21, 39, 192, 'Hộ kinh doanh Thạo Loan', 'Hộ kinh doanh Thạo Loan', NULL, 'MBBank', '0987654321', 'HỘ KINH DOANH THẠO LOAN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%98+KINH+DOANH+TH%E1%BA%A0O+LOAN&addInfo=TT+H%E1%BB%99+kinh+doanh+Th%E1%BA%A1o+Loan', 'Rượu Bạch cúc Long Tửu', 120000.00, 'chai', 'Chủ thể sản xuất: Hộ kinh doanh Thạo Loan\nCăn cứ pháp lý & Địa chỉ: Thôn Xuân Canh, xã Đông Anh; QĐ số 560/QĐ-UBND ngày 27/1/2021\nPhân hạng OCOP: 3 sao (Năm công nhận 2024)\n\nĐịa chỉ cơ sở: Thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, TP. Hà Nội\nQuản lý: Tích hợp mã QR kiểm soát truy xuất nguồn gốc trên Hệ thống nông sản Hà Nội.\n\nThông tin chi tiết Rượu Bạch cúc Long Tửu (Rượu Hoa cúc Long Tửu):\n- Quy cách: Chai thủy tinh cao cấp 500ml nhãn mác mang đậm dấu ấn làng nghề truyền thống Đông Anh.\n- Nguyên liệu: Hoa bạch cúc (hoa cúc trắng thảo dược) sấy khô nguyên bông tinh khiết kết hợp Rượu gạo nếp Long Tửu cốt qua máy lọc đa tầng khử sạch độc tố Methanol và Aldehyde.\n- Hương vị cảm quan: Sắc vàng nhạt óng ả trong vắt. Hương thơm thảo mộc tự nhiên dịu nhẹ thanh mát hoa cúc. Nồng độ êm mượt (29% - 32% Vol), vị cay nhẹ hòa quyện hậu vị ngọt thanh sâu lắng, uống không đau đầu mệt mỏi.\n\nHướng dẫn thưởng thức & Bảo quản:\n- Thưởng thức ngon nhất: Ướp lạnh sâu trong ngăn mát tủ lạnh, thích hợp làm đồ khai vị thanh lịch (1 - 2 chén nhỏ trong bữa ăn).\n- Công dụng: Thanh nhiệt giải độc mát gan sáng mắt, giảm đau đầu an thần giúp giấc ngủ sâu, kích thích tiêu hóa ăn ngon miệng.\n- Bảo quản: Nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785468049_ZQn6Xi3D.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2024', 'Rượu Bạch cúc Long Tửu (còn gọi là Rượu Hoa cúc Long Tửu) là dòng sản phẩm rượu hoa truyền thống đặc sắc nằm trong bộ ba Rượu Long Tửu danh tiếng đạt chứng nhận OCOP 3 sao của Hộ kinh doanh Thạo Loan tại thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, Hà Nội.\n\nTác phẩm độc đáo này kết hợp tinh tế giữa những bông hoa bạch cúc trắng sấy khô nguyên bông tinh khiết và dòng Rượu gạo nếp Long Tửu cốt chưng cất men thuốc bắc 36 vị. Cốt rượu được tinh lọc qua hệ thống máy lọc hiện đại nhằm triệt tiêu hoàn toàn độc tố Methanol và Aldehyde. Trải qua quá trình ngâm ủ kỹ lưỡng dài ngày trong chum sành, từng giọt rượu đọng lại sắc vàng nhạt óng ả trong vắt, phảng phất hương thơm thảo mộc tự nhiên ngát hương hoa cúc. Khi thưởng thức, nồng độ êm mượt cùng vị ngọt thanh sâu lắng mang lại cảm giác an thần, giải độc mát gan và thư thái tinh thần tuyệt đối.', 'Nghệ nhân Nguyễn Văn Thạo & Hộ kinh doanh Thạo Loan (Thôn Xuân Canh, Xã Xuân Canh, Đông Anh)', NULL, 'Rượu Bạch cúc Long Tửu là sản phẩm rượu hoa thảo mộc thượng hạng đạt chứng nhận OCOP 3 sao Cấp Thành phố của Hộ kinh doanh Thạo Loan, thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh. Được chế tác từ những bông cúc trắng tinh khiết ngâm ủ trong rượu nếp gia truyền lọc sạch độc tố, giọt rượu sắc vàng nhạt óng ả mang hương thơm thảo mộc thanh dịu, vị êm mượt thanh ngọt giúp mát gan, sáng mắt và an thần ngon giấc.', '[\"Hoa b\\u1ea1ch c\\u00fac tr\\u1eafng s\\u1ea5y kh\\u00f4 nguy\\u00ean b\\u00f4ng\",\"R\\u01b0\\u1ee3u n\\u1ebfp Long T\\u1eedu c\\u1ed1t tinh l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c t\\u1ed1\",\"Men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb gia truy\\u1ec1n\",\"Tinh ch\\u1ea5t th\\u1ea3o m\\u1ed9c hoa c\\u00fac t\\u1ef1 nhi\\u00ean\"]', '[{\"year\":\"R\\u01b0\\u1ee3u Hoa Th\\u1ea3o D\\u01b0\\u1ee3c\",\"event\":\"H\\u1ed9 kinh doanh Th\\u1ea1o Loan ng\\u00e2m \\u1ee7 th\\u00e0nh c\\u00f4ng d\\u00f2ng R\\u01b0\\u1ee3u B\\u1ea1ch c\\u00fac t\\u1eeb hoa c\\u00fac tr\\u1eafng.\"},{\"year\":\"Tinh l\\u1ecdc \\u0111a t\\u1ea7ng\",\"event\":\"\\u0110\\u1ea7u t\\u01b0 m\\u00e1y l\\u1ecdc \\u0111a t\\u1ea7ng kh\\u1eed s\\u1ea1ch \\u0111\\u1ed9c t\\u1ed1 Methanol v\\u00e0 Aldehyde b\\u1ea3o v\\u1ec7 s\\u1ee9c kh\\u1ecfe.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"R\\u01b0\\u1ee3u B\\u1ea1ch c\\u00fac Long T\\u1eedu \\u0111\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"}]'),
(22, 41, 195, 'Cơ sở sản xuất thực phẩm Liêm Hiệp', 'Cơ sở sản xuất thực phẩm Liêm Hiệp', NULL, 'MBBank', '0987654321', 'CƠ SỞ SẢN XUẤT THỰC PHẨM LIÊM HIỆP', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C6%A0+S%E1%BB%9E+S%E1%BA%A2N+XU%E1%BA%A4T+TH%E1%BB%B0C+PH%E1%BA%A8M+LI%C3%8AM+HI%E1%BB%86P&addInfo=TT+C%C6%A1+s%E1%BB%9F+s%E1%BA%A3n+xu%E1%BA%A5t+th%E1%BB%B1c+ph%E1%BA%A9m+Li%C3%AAm+Hi%E1%BB%87p', 'Giò lụa Liêm Hiệp', 180000.00, 'kg', 'Chủ thể sản xuất: Cơ sở sản xuất thực phẩm Liêm Hiệp\nCăn cứ pháp lý & Địa chỉ: Xóm Thượng, xã Đông Anh, huyện Đông Anh, TP. Hà Nội\nPhân hạng OCOP: 3 sao Cấp Thành phố / Huyện Đông Anh (Năm công nhận 2025).\nTiêu chuẩn an toàn: Đạt chứng nhận đủ điều kiện An Toàn Vệ Sinh Thực Phẩm của Bộ Y tế, có kiểm dịch thú y rõ ràng.\n\nThông tin chi tiết Giò lụa Liêm Hiệp:\n- Nguyên liệu: 100% Thịt lợn mông nạc dẻo tươi mới mổ trong ngày kết hợp nước mắm cốt nguyên chất thượng hạng.\n- Tiêu chuẩn 3 KHÔNG: Không hàn the - Không trộn bột thực phẩm - Không chất bảo quản độc hại.\n- Cảm quan hương vị: Màu hồng nhạt tự nhiên của thịt tươi, bề mặt mịn màng mọng nước xuất hiện lỗ khí nhỏ chuẩn kỹ thuật giã quết. Khi ăn dai giòn sần sật, ngọt đằm đậm đà hương nước mắm cốt.\n\nHướng dẫn đóng gói & Bảo quản:\n- Quy cách: Đóng khuôn lót lá chuối xanh thơm ngậy, bên ngoài bọc túi phức hợp hút chân không kín khí.\n- Cung ứng: Chuyên cung cấp bán sỉ/lẻ và suất ăn quy mô lớn cho trường học, bếp ăn công nghiệp, nhà hàng tại Đông Anh.\n- Bảo quản: Ngăn mát tủ lạnh (2 - 4°C) dùng trong 7 ngày, hoặc ngăn đá bảo quản 1 tháng.', 'https://media.xadonganh.com/ocop/1785461275_oOOAPuo9.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:31:21', '2025', 'Giò lụa Liêm Hiệp là đặc sản thực phẩm truyền thống trứ danh đạt chứng nhận OCOP 3 sao của Cơ sở sản xuất thực phẩm Liêm Hiệp tại Xóm Thượng, xã Đông Anh, huyện Đông Anh, Hà Nội.\n\nTuyển chọn từ những tảng thịt lợn mông nạc tươi dẻo nóng hổi vừa ra lò mổ có kiểm dịch thú y khắt khe, qua bàn tay giã quết khéo léo gia truyền kết hợp nước mắm cốt hảo hạng, sản phẩm tuyệt đối tuân thủ tiêu chuẩn \'3 Không\' (Không hàn the, Không trộn bột, Không chất bảo quản). Được bọc kỹ bằng lớp lá chuối tươi tự nhiên bên trong và hút chân không kín khí bên ngoài, từng lát giò lụa Liêm Hiệp khi cắt ra luôn ánh sắc hồng mọng nước, dai giòn tự nhiên thơm phức, mang hương vị ấm cúng thơm ngon đậm đà cho mọi bữa ăn gia đình và bếp ăn trường học.', 'Chủ cơ sở sản xuất thực phẩm Liêm Hiệp (Xóm Thượng, Đông Anh)', NULL, 'Giò lụa Liêm Hiệp là đặc sản đạt chứng nhận OCOP 3 sao của Cơ sở sản xuất thực phẩm Liêm Hiệp, Xóm Thượng, xã Đông Anh. Được chế biến từ thịt lợn mông nạc tươi dẻo quánh theo tiêu chuẩn 3 Không (không hàn the, không trộn bột, không chất bảo quản), từng khoanh giò lụa lót lá chuối xanh hút chân không mang sắc hồng mịn mọng nước, dai giòn sần sật tự nhiên thơm phức đằm thắm.', '[\"Th\\u1ecbt l\\u1ee3n m\\u00f4ng n\\u1ea1c t\\u01b0\\u01a1i n\\u00f3ng m\\u1ed5 trong ng\\u00e0y (95%)\",\"N\\u01b0\\u1edbc m\\u1eafm c\\u1ed1t nguy\\u00ean ch\\u1ea5t th\\u01b0\\u1ee3ng h\\u1ea1ng\",\"Gia v\\u1ecb t\\u1ef1 nhi\\u00ean gia truy\\u1ec1n\",\"L\\u00e1 chu\\u1ed1i xanh g\\u00f3i truy\\u1ec1n th\\u1ed1ng\"]', '[{\"year\":\"L\\u00f2 m\\u1ed5 ki\\u1ec3m d\\u1ecbch\",\"event\":\"Tuy\\u1ec3n ch\\u1ecdn ngu\\u1ed3n th\\u1ecbt l\\u1ee3n t\\u01b0\\u01a1i n\\u00f3ng d\\u1ebbo qu\\u00e1nh t\\u1eeb c\\u00e1c l\\u00f2 m\\u1ed5 c\\u00f3 ki\\u1ec3m d\\u1ecbch th\\u00fa y kh\\u1eaft khe.\"},{\"year\":\"Ti\\u00eau chu\\u1ea9n 3 KH\\u00d4NG\",\"event\":\"Cam k\\u1ebft kh\\u00f4ng h\\u00e0n the, kh\\u00f4ng tr\\u1ed9n b\\u1ed9t th\\u1ef1c ph\\u1ea9m, kh\\u00f4ng ch\\u1ea5t b\\u1ea3o qu\\u1ea3n.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"\\u0110\\u01b0\\u1ee3c UBND c\\u00f4ng nh\\u1eadn s\\u1ea3n ph\\u1ea9m OCOP 3 sao cung \\u1ee9ng quy m\\u00f4 l\\u1edbn cho c\\u00e1c tr\\u01b0\\u1eddng h\\u1ecdc v\\u00e0 b\\u1ebfp \\u0103n.\"}]'),
(23, 41, 195, 'Cơ sở sản xuất thực phẩm Liêm Hiệp', 'Cơ sở sản xuất thực phẩm Liêm Hiệp', NULL, 'MBBank', '0987654321', 'CƠ SỞ SẢN XUẤT THỰC PHẨM LIÊM HIỆP', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C6%A0+S%E1%BB%9E+S%E1%BA%A2N+XU%E1%BA%A4T+TH%E1%BB%B0C+PH%E1%BA%A8M+LI%C3%8AM+HI%E1%BB%86P&addInfo=TT+C%C6%A1+s%E1%BB%9F+s%E1%BA%A3n+xu%E1%BA%A5t+th%E1%BB%B1c+ph%E1%BA%A9m+Li%C3%AAm+Hi%E1%BB%87p', 'Chả lụa Liêm Hiệp', 180000.00, 'kg', 'Chủ thể sản xuất: Cơ sở sản xuất thực phẩm Liêm Hiệp\nCăn cứ pháp lý & Địa chỉ: Xóm Thượng, xã Đông Anh, huyện Đông Anh, TP. Hà Nội\nPhân hạng OCOP: 3 sao Cấp Thành phố / Huyện Đông Anh (Năm công nhận 2025).\nTiêu chuẩn an toàn: Đạt chứng nhận đủ điều kiện An Toàn Vệ Sinh Thực Phẩm của Bộ Y tế, có kiểm dịch thú y rõ ràng.\n\nThông tin chi tiết Chả lụa Liêm Hiệp:\n- Nguyên liệu: 100% Thịt lợn mông nạc dẻo tươi mới mổ trong ngày kết hợp nước mắm cốt nguyên chất thượng hạng.\n- Tiêu chuẩn 3 KHÔNG: Không hàn the - Không trộn bột thực phẩm - Không chất bảo quản độc hại.\n- Cảm quan hương vị: Màu hồng nhạt tự nhiên của thịt tươi, bề mặt mịn màng mọng nước xuất hiện lỗ khí nhỏ chuẩn kỹ thuật giã quết. Khi ăn dai giòn sần sật, ngọt đằm đậm đà hương nước mắm cốt.\n\nHướng dẫn đóng gói & Bảo quản:\n- Quy cách: Đóng khuôn lót lá chuối xanh thơm ngậy, bên ngoài bọc túi phức hợp hút chân không kín khí.\n- Cung ứng: Chuyên cung cấp bán sỉ/lẻ và suất ăn quy mô lớn cho trường học, bếp ăn công nghiệp, nhà hàng tại Đông Anh.\n- Bảo quản: Ngăn mát tủ lạnh (2 - 4°C) dùng trong 7 ngày, hoặc ngăn đá bảo quản 1 tháng.', 'https://media.xadonganh.com/ocop/1785461571_hQSVzazH.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:31:21', '2025', 'Chả lụa Liêm Hiệp là đặc sản thực phẩm truyền thống trứ danh đạt chứng nhận OCOP 3 sao của Cơ sở sản xuất thực phẩm Liêm Hiệp tại Xóm Thượng, xã Đông Anh, huyện Đông Anh, Hà Nội.\n\nTuyển chọn từ những tảng thịt lợn mông nạc tươi dẻo nóng hổi vừa ra lò mổ có kiểm dịch thú y khắt khe, qua bàn tay giã quết khéo léo gia truyền kết hợp nước mắm cốt hảo hạng, sản phẩm tuyệt đối tuân thủ tiêu chuẩn \'3 Không\' (Không hàn the, Không trộn bột, Không chất bảo quản). Được bọc kỹ bằng lớp lá chuối tươi tự nhiên bên trong và hút chân không kín khí bên ngoài, từng lát chả lụa Liêm Hiệp khi cắt ra luôn ánh sắc hồng mọng nước, dai giòn tự nhiên thơm phức, mang hương vị ấm cúng thơm ngon đậm đà cho mọi bữa ăn gia đình và bếp ăn trường học.', 'Chủ cơ sở sản xuất thực phẩm Liêm Hiệp (Xóm Thượng, Đông Anh)', NULL, 'Chả lụa Liêm Hiệp là đặc sản đạt chứng nhận OCOP 3 sao của Cơ sở sản xuất thực phẩm Liêm Hiệp, Xóm Thượng, xã Đông Anh. Được chế biến từ thịt lợn mông nạc tươi dẻo quánh theo tiêu chuẩn 3 Không (không hàn the, không trộn bột, không chất bảo quản), từng khoanh chả lụa lót lá chuối xanh hút chân không mang sắc hồng mịn mọng nước, dai giòn sần sật tự nhiên thơm phức đằm thắm.', '[\"Th\\u1ecbt l\\u1ee3n m\\u00f4ng n\\u1ea1c t\\u01b0\\u01a1i n\\u00f3ng m\\u1ed5 trong ng\\u00e0y (95%)\",\"N\\u01b0\\u1edbc m\\u1eafm c\\u1ed1t nguy\\u00ean ch\\u1ea5t th\\u01b0\\u1ee3ng h\\u1ea1ng\",\"Gia v\\u1ecb t\\u1ef1 nhi\\u00ean gia truy\\u1ec1n\",\"L\\u00e1 chu\\u1ed1i xanh g\\u00f3i truy\\u1ec1n th\\u1ed1ng\"]', '[{\"year\":\"L\\u00f2 m\\u1ed5 ki\\u1ec3m d\\u1ecbch\",\"event\":\"Tuy\\u1ec3n ch\\u1ecdn ngu\\u1ed3n th\\u1ecbt l\\u1ee3n t\\u01b0\\u01a1i n\\u00f3ng d\\u1ebbo qu\\u00e1nh t\\u1eeb c\\u00e1c l\\u00f2 m\\u1ed5 c\\u00f3 ki\\u1ec3m d\\u1ecbch th\\u00fa y kh\\u1eaft khe.\"},{\"year\":\"Ti\\u00eau chu\\u1ea9n 3 KH\\u00d4NG\",\"event\":\"Cam k\\u1ebft kh\\u00f4ng h\\u00e0n the, kh\\u00f4ng tr\\u1ed9n b\\u1ed9t th\\u1ef1c ph\\u1ea9m, kh\\u00f4ng ch\\u1ea5t b\\u1ea3o qu\\u1ea3n.\"},{\"year\":\"OCOP 3 Sao\",\"event\":\"\\u0110\\u01b0\\u1ee3c UBND c\\u00f4ng nh\\u1eadn s\\u1ea3n ph\\u1ea9m OCOP 3 sao cung \\u1ee9ng quy m\\u00f4 l\\u1edbn cho c\\u00e1c tr\\u01b0\\u1eddng h\\u1ecdc v\\u00e0 b\\u1ebfp \\u0103n.\"}]'),
(24, 36, 189, 'Công ty TNHH Hoàng Chiến Thắng', 'Công ty TNHH Hoàng Chiến Thắng', NULL, 'MBBank', '0987654321', 'CÔNG TY TNHH HOÀNG CHIẾN THẮNG', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C3%94NG+TY+TNHH+HO%C3%80NG+CHI%E1%BA%BEN+TH%E1%BA%AENG&addInfo=TT+C%C3%B4ng+ty+TNHH+Ho%C3%A0ng+Chi%E1%BA%BFn+Th%E1%BA%AFng', 'Bánh vừng Cookies', 30000.00, 'gói', 'Chủ thể sản xuất: Công ty TNHH Hoàng Chiến Thắng\nCăn cứ pháp lý & Địa chỉ: Thôn Đông Ngàn, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 3 sao (Năm công nhận 2025)\nThông tin thanh toán: 125349089 tại ngân hàng Acb\nKênh phân phối: Bán các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa\n\nCông ty TNHH Hoàng Chiến Thắng xin kính chào quý khách, cảm ơn quý khách đã sử dụng sản phẩm Bánh vừng Cookies!\nĐịa chỉ sản xuất: Thôn Đông Ngàn, xã Đông Hội, huyện Đông Anh, TP. Hà Nội\nHotline: 0243.984.325 | Email: Chienthang1986@gmail.com\n\n1. Hướng dẫn sử dụng & Bảo quản:\n- Sản phẩm ăn ngay không cần chế biến\n- Bảo quản ở nơi thoáng mát, sạch sẽ\n- Đậy kín miệng túi sau mỗi lần sử dụng\n\n2. Thành phần: Bột mỳ (95%), vừng rang cốt lõi, đường kính, nước sạch, dầu ăn, muối ăn, bột khai Ammonium Bicarbonate, trứng tươi.\n\n3. Thời hạn sử dụng: 12 tháng kể từ ngày sản xuất.', 'https://media.xadonganh.com/ocop/1785471035_YHZkScUY.png', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2025', 'Ở vùng quê Đông Hội - Đông Anh gạo trắng nước trong, thương hiệu Chiến Thắng nổi tiếng với đặc sản Bánh vừng Cookies cổ truyền dân tộc. Làng Đông Ngàn nằm bên bãi bồi sông Hồng trù phú sung túc qua bao đời. Để tạo nên chiếc bánh vừng Cookies thơm ngon đạt chuẩn an toàn thực phẩm, khâu đầu tiên và quan trọng nhất chính là hạt vừng rang chín vàng - cốt lõi làm nên tên gọi và linh hồn của sản phẩm.\n\nTrải qua nhiều năm gây dựng, Công ty TNHH Hoàng Chiến Thắng vẫn gìn giữ trọn vẹn nét đẹp của nghề làm bánh truyền thống, kết hợp cùng tiêu chuẩn chế biến hiện đại để tạo nên hương vị bùi béo giòn rụm khó quên của xứ Cố Đô Đông Anh.', 'Nghệ nhân chế biến Công ty TNHH Hoàng Chiến Thắng (Thôn Đông Ngàn, Xã Đông Hội)', NULL, 'Bánh vừng Cookies là đặc sản nức tiếng của làng Đông Ngàn, xã Đông Hội, huyện Đông Anh do Công ty TNHH Hoàng Chiến Thắng sản xuất. Điểm cốt lõi tạo nên linh hồn của bánh chính là những hạt vừng rang chín vàng đơm thơm bùi quyện cùng bột mỳ và trứng tươi. Với vị giòn rụm, ngọt nhẹ béo thơm và thời hạn sử dụng 12 tháng, Bánh vừng Cookies là thức quà quê hương đầm ấm dành tặng người thân và du khách gần xa.', '[\"V\\u1eebng rang ch\\u00edn c\\u1ed1t l\\u00f5i\",\"B\\u1ed9t m\\u1ef3 (95%)\",\"Tr\\u1ee9ng t\\u01b0\\u01a1i\",\"\\u0110\\u01b0\\u1eddng k\\u00ednh\",\"N\\u01b0\\u1edbc s\\u1ea1ch\",\"D\\u1ea7u \\u0103n\",\"Mu\\u1ed1i \\u0103n\",\"B\\u1ed9t khai Ammonium Bicarbonate\"]', '[{\"year\":\"L\\u00e0ng ngh\\u1ec1\",\"event\":\"L\\u00e0ng \\u0110\\u00f4ng Ng\\u00e0n b\\u00ean b\\u00e3i b\\u1ed3i s\\u00f4ng H\\u1ed3ng ph\\u00e1t tri\\u1ec3n ngh\\u1ec1 l\\u00e0m b\\u00e1nh v\\u1eebng c\\u1ed5 truy\\u1ec1n n\\u1ee9c ti\\u1ebfng.\"},{\"year\":\"G\\u00e2y d\\u1ef1ng\",\"event\":\"C\\u00f4ng ty TNHH Ho\\u00e0ng Chi\\u1ebfn Th\\u1eafng nghi\\u00ean c\\u1ee9u chu\\u1ea9n h\\u00f3a c\\u00f4ng th\\u1ee9c B\\u00e1nh v\\u1eebng Cookies th\\u01a1m b\\u00f9i.\"},{\"year\":\"OCOP\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao UBND Huy\\u1ec7n \\u0110\\u00f4ng Anh.\"},{\"year\":\"Ph\\u00e2n ph\\u1ed1i\",\"event\":\"Ph\\u00e2n ph\\u1ed1i r\\u1ed9ng kh\\u1eafp c\\u00e1c \\u0111\\u1ea1i l\\u00fd, si\\u00eau th\\u1ecb v\\u00e0 gian h\\u00e0ng \\u0111\\u1eb7c s\\u1ea3n \\u0110\\u00f4ng Anh.\"}]'),
(25, 36, 189, 'Công ty TNHH Hoàng Chiến Thắng', 'Công ty TNHH Hoàng Chiến Thắng', NULL, 'MBBank', '0987654321', 'CÔNG TY TNHH HOÀNG CHIẾN THẮNG', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=C%C3%94NG+TY+TNHH+HO%C3%80NG+CHI%E1%BA%BEN+TH%E1%BA%AENG&addInfo=TT+C%C3%B4ng+ty+TNHH+Ho%C3%A0ng+Chi%E1%BA%BFn+Th%E1%BA%AFng', 'Bánh gạo thơm', 30000.00, 'gói', 'Chủ thể sản xuất: Công ty TNHH Hoàng Chiến Thắng\nCăn cứ pháp lý & Địa chỉ: Thôn Đông Ngàn, xã Đông Anh, TP. Hà Nội; QĐ số 2008/QĐ-UBND ngày 7/4/2023\nPhân hạng OCOP: 3 sao (Năm công nhận 2025)\nThông tin thanh toán: 125349089 tại ngân hàng Acb\nKênh phân phối: Bán các siêu thị, cửa hàng tiện ích, cửa hàng tạp hóa\n\nCông ty TNHH Hoàng Chiến Thắng xin kính chào quý khách, cảm ơn quý khách đã sử dụng sản phẩm Bánh Gạo Thơm!\n\nThông tin chi tiết sản phẩm Bánh Gạo Thơm:\n- Bánh gạo thơm giòn tan bùi ngọt thanh dịu từ tinh túy hạt gạo phù sa sông Hồng Đông Anh.\n\n1. Hướng dẫn sử dụng & Bảo quản:\n- Sản phẩm ăn ngay không cần chế biến\n- Bảo quản ở nơi thoáng mát, sạch sẽ\n- Đậy kín miệng túi sau mỗi lần sử dụng\n\n2. Thành phần: Bột mỳ (95%), bột gạo thơm phù sa chọn lọc, đường kính, nước sạch, dầu ăn, muối ăn, bột khai Ammonium Bicarbonate, trứng tươi.\n\n3. Thời hạn sử dụng: 12 tháng kể từ ngày sản xuất.', 'https://media.xadonganh.com/ocop/1785471541_BQJdLFhQ.png', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:19:22', '2025', 'Vùng đất Đông Anh được biết đến là một nơi sản xuất ra những hạt gạo thơm ngon, kết tinh sự thơm ngọt dạt dào của phù sa sông Hồng. Kết hợp với sự khéo léo của những người thợ làm bánh lành nghề, Công ty TNHH Hoàng Chiến Thắng đã tạo nên sản phẩm Bánh Gạo Thơm nức tiếng xa gần.\n\nSản phẩm Bánh Gạo Thơm Chiến Thắng có vị ngọt thanh dịu, bánh giòn tan béo bùi vị gạo tự nhiên. Bánh ăn nhiều không bị ngấy, thích hợp cho các bữa ăn nhẹ, điểm tâm và đặc biệt thơm ngon khi thưởng thức cùng các loại trà ấm trong những dịp gia đình đoàn viên.', 'Đội ngũ chế biến Công ty TNHH Hoàng Chiến Thắng (Đông Anh)', NULL, 'Bánh Gạo Thơm là sản phẩm OCOP được yêu thích của Công ty TNHH Hoàng Chiến Thắng, huyện Đông Anh. Bánh mang lại vị ngọt thanh, kết cấu giòn tan và thơm bùi đậm đà từ những hạt gạo phù sa sông Hồng. Không gây ngấy khi thưởng thức và có thời hạn sử dụng 12 tháng, Bánh Gạo Thơm là món quà ẩm thực tinh tế, thích hợp dùng làm điểm tâm hoặc thưởng thức cùng trà ấm mỗi ngày.', '[\"B\\u1ed9t g\\u1ea1o th\\u01a1m ph\\u00f9 sa s\\u00f4ng H\\u1ed3ng\",\"B\\u1ed9t m\\u1ef3 tuy\\u1ec3n ch\\u1ecdn (95%)\",\"Tr\\u1ee9ng t\\u01b0\\u01a1i\",\"\\u0110\\u01b0\\u1eddng k\\u00ednh\",\"N\\u01b0\\u1edbc s\\u1ea1ch\",\"D\\u1ea7u \\u0103n\",\"Mu\\u1ed1i \\u0103n\",\"B\\u1ed9t khai Ammonium Bicarbonate\"]', '[{\"year\":\"Ngu\\u1ed3n g\\u1ed1c\",\"event\":\"H\\u1ea1t g\\u1ea1o th\\u01a1m ph\\u00f9 sa s\\u00f4ng H\\u1ed3ng \\u0110\\u00f4ng Anh \\u0111\\u01b0\\u1ee3c k\\u1ebft tinh v\\u00e0o c\\u00f4ng th\\u1ee9c b\\u00e1nh truy\\u1ec1n th\\u1ed1ng.\"},{\"year\":\"Ch\\u1ebf bi\\u1ebfn\",\"event\":\"C\\u00f4ng ty TNHH Ho\\u00e0ng Chi\\u1ebfn Th\\u1eafng chu\\u1ea9n h\\u00f3a d\\u00e2y chuy\\u1ec1n s\\u1ea3n xu\\u1ea5t B\\u00e1nh G\\u1ea1o Th\\u01a1m \\u0111\\u1ea1t chu\\u1ea9n ATTP.\"},{\"year\":\"OCOP\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 3 sao UBND Huy\\u1ec7n \\u0110\\u00f4ng Anh.\"},{\"year\":\"Ph\\u00e2n ph\\u1ed1i\",\"event\":\"S\\u1ea3n ph\\u1ea9m \\u0111\\u01b0\\u1ee3c \\u0111\\u00f4ng \\u0111\\u1ea3o ng\\u01b0\\u1eddi ti\\u00eau d\\u00f9ng y\\u00eau th\\u00edch v\\u00e0 ph\\u00e2n ph\\u1ed1i r\\u1ed9ng kh\\u1eafp c\\u1ea3 n\\u01b0\\u1edbc.\"}]'),
(26, 39, 192, 'Hộ kinh doanh Thạo Loan', 'Hộ kinh doanh Thạo Loan', NULL, 'MBBank', '0987654321', 'HỘ KINH DOANH THẠO LOAN', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=H%E1%BB%98+KINH+DOANH+TH%E1%BA%A0O+LOAN&addInfo=TT+H%E1%BB%99+kinh+doanh+Th%E1%BA%A1o+Loan', 'Rượu gạo nếp Long tửu', 65000.00, 'lít', 'Chủ thể sản xuất: Hộ kinh doanh Thạo Loan\r\nCăn cứ pháp lý & Địa chỉ: Thôn Xuân Canh, xã Đông Anh; QĐ số 7059/QĐ-UBND ngày 13/12/2019\r\nPhân hạng OCOP: 3 sao (Năm công nhận 2025)\r\n\r\nĐịa chỉ cơ sở: Thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, TP. Hà Nội\r\nQuản lý: Dán tem OCOP chính thức và tích hợp mã QR đồng bộ trên Cổng thông tin truy xuất nguồn gốc nông sản Hà Nội.\r\n\r\nThông tin chi tiết Rượu gạo nếp Long Tửu:\r\n- Quy cách: Chai thủy tinh 500ml - 750ml thiết kế sang trọng lịch sự.\r\n- Kỹ thuật chế tác: Chưng cất men thuốc bắc 36 vị gia truyền kết hợp gạo nếp hoa vàng thuần khiết. Cốt rượu đi qua máy lọc hiện đại khử sạch Methanol và Aldehyde, ủ chín ngấu trong chum sành.\r\n- Cảm quan hương vị: Rượu trong vắt, hương thơm nồng nàn gạo nếp hoa vàng, uống êm dịu đằm thắm, không đau đầu khát nước.\r\n\r\nHướng dẫn sử dụng & Bảo quản:\r\n- Thưởng thức: Uống trực tiếp hoặc ướp lạnh trong các bữa tiệc gia đình, hội nghị, cưới hỏi.\r\n- Bảo quản: Nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.', 'https://media.xadonganh.com/ocop/1785468091_94XIP9g7.jpg', '3 sao', '2026-07-27 03:31:12', '2026-08-01 04:40:41', '2025', 'Rượu gạo nếp Long Tửu là sản phẩm rượu truyền thống trứ danh của Hộ kinh doanh Thạo Loan tại thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh, Hà Nội. Tác phẩm xuất sắc đạt chứng nhận OCOP 4 sao Cấp Thành Phố theo Quyết định số 7059/QĐ-UBND.\n\nĐược chưng cất theo phương pháp gia truyền ủ men thuốc bắc 36 vị kết hợp gạo nếp hoa vàng thuần khiết trên vùng đất bãi bồi Xuân Canh, giọt rượu nếp Long Tửu đi qua hệ thống máy lọc đa tầng khử sạch độc tố Aldehyde và Methanol trước khi ngâm ủ chín ngấu trong chum sành. Khi thưởng thức, rượu mang lại vị êm mượt nồng nàn, hậu vị ngọt đậm đà đằm thắm quyến rũ, tôn vinh nét đẹp văn hóa ẩm thực truyền thống Đông Anh.', 'Nghệ nhân Nguyễn Văn Thạo & Hộ kinh doanh Thạo Loan (Thôn Xuân Canh, Xã Xuân Canh, Đông Anh)', NULL, 'Rượu gạo nếp Long Tửu là sản phẩm đặc sản OCOP 4 sao của Hộ kinh doanh Thạo Loan, thôn Xuân Canh, xã Xuân Canh, huyện Đông Anh. Được chưng cất từ gạo nếp hoa vàng ủ men thuốc bắc 36 vị và ngâm chum sành khử sạch độc tố, giọt rượu trong vắt mang hương thơm nồng nàn, vị êm dịu đằm thắm tuyệt đối an toàn cho sức khỏe.', '[\"G\\u1ea1o n\\u1ebfp c\\u00e1i hoa v\\u00e0ng thu\\u1ea7n khi\\u1ebft\",\"Men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb gia truy\\u1ec1n\",\"N\\u01b0\\u1edbc s\\u1ea1ch tinh khi\\u1ebft Xu\\u00e2n Canh\",\"\\u1ee6 chum s\\u00e0nh h\\u1ea1 th\\u1ed5 truy\\u1ec1n th\\u1ed1ng\"]', '[{\"year\":\"Men gia truy\\u1ec1n\",\"event\":\"Bao \\u0111\\u1eddi l\\u00e0m ngh\\u1ec1 ch\\u01b0ng c\\u1ea5t r\\u01b0\\u1ee3u n\\u1ebfp men thu\\u1ed1c b\\u1eafc 36 v\\u1ecb t\\u1ea1i l\\u00e0ng Xu\\u00e2n Canh.\"},{\"year\":\"M\\u00e1y l\\u1ecdc \\u0111a t\\u1ea7ng\",\"event\":\"\\u0110\\u1ea7u t\\u01b0 h\\u1ec7 th\\u1ed1ng c\\u00f4ng ngh\\u1ec7 l\\u1ecdc kh\\u1eed \\u0111\\u1ed9c t\\u1ed1 Aldehyde & Methanol an to\\u00e0n tuy\\u1ec7t \\u0111\\u1ed1i.\"},{\"year\":\"OCOP 4 Sao\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP 4 sao C\\u1ea5p Th\\u00e0nh ph\\u1ed1 theo Q\\u0110 s\\u1ed1 7059\\/Q\\u0110-UBND.\"}]');
INSERT INTO `ocop_products` (`id`, `eatery_id`, `user_id`, `stall_name`, `seller_name`, `seller_phone`, `bank_name`, `bank_account`, `bank_holder`, `qr_code_path`, `name`, `price`, `unit`, `description`, `image_path`, `star_rating`, `created_at`, `updated_at`, `heritage_year`, `story`, `artisans`, `fun_fact`, `audio_narrative`, `ingredients`, `timeline`) VALUES
(27, 40, 193, 'HTX dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa', 'Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa', NULL, 'MBBank', '0987654321', 'HTX DỊCH VỤ NÔNG NGHIỆP KINH DOANH TỔNG HỢP CỔ LOA', 'https://img.vietqr.io/image/MB-0987654321-compact.png?accountName=HTX+D%E1%BB%8ACH+V%E1%BB%A4+N%C3%94NG+NGHI%E1%BB%86P+KINH+DOANH+T%E1%BB%94NG+H%E1%BB%A2P+C%E1%BB%94+LOA&addInfo=TT+HTX+d%E1%BB%8Bch+v%E1%BB%A5+n%C3%B4ng+nghi%E1%BB%87p+kinh+doanh+t%E1%BB%95ng+h%E1%BB%A3p+C%E1%BB%95+Loa', 'Bí đỏ', 20000.00, 'kg', 'Chủ thể sản xuất: Hợp tác xã dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa\nCăn cứ pháp lý & Địa chỉ: Trung tâm Cổ Loa xã Đông Anh; QĐ số 1441/QĐ-UBND ngày 28/4/2022\nPhân hạng OCOP: 3 sao (Năm công nhận 2025)\n\nĐịa chỉ: Thôn Cổ Loa, xã Cổ Loa, huyện Đông Anh, TP. Hà Nội\n\nThông tin chi tiết Bí đỏ Cổ Loa:\n- Nông sản an toàn gieo trồng trên vùng đất bãi phù sa màu mỡ sông Hoàng Giang Cổ Loa.\n- Quy trình chăm sóc sinh học theo tiêu chuẩn VietGAP, không sử dụng hóa chất bảo vệ thực phẩm độc hại.\n- Tươi ngon đậm đà giàu dinh dưỡng tự nhiên.', 'https://media.xadonganh.com/ocop/1785462218_tWFWxxV8.jpg', '3 sao', '2026-07-27 03:31:12', '2026-07-31 09:13:31', '2025', 'Bí đỏ Cổ Loa là sản phẩm nông sản sạch đạt chứng nhận OCOP của HTX dịch vụ nông nghiệp kinh doanh tổng hợp Cổ Loa, mảnh đất di sản Cố đô Cổ Loa lịch sử. Được nuôi dưỡng bởi phù sa màu mỡ và bàn tay chăm sóc cần cù của bà con nông dân, sản phẩm đảm bảo tiêu chuẩn an toàn VietGAP tươi ngon giàu dinh dưỡng.', 'Bà con nông dân HTX Nông nghiệp Cổ Loa (Thôn Cổ Loa, Đông Anh)', NULL, 'Bí đỏ Cổ Loa là nông sản sạch đạt chứng nhận OCOP của HTX nông nghiệp Cổ Loa, huyện Đông Anh. Được gieo trồng theo chuẩn VietGAP an toàn sinh học trên vùng đất bãi Cổ Loa, sản phẩm mang lại nguồn thực phẩm tươi ngon giàu dinh dưỡng cho mọi gia đình.', '[\"100% N\\u00f4ng s\\u1ea3n t\\u01b0\\u01a1i s\\u1ea1ch gieo tr\\u1ed3ng t\\u1ea1i v\\u00f9ng di s\\u1ea3n C\\u1ed5 Loa\"]', '[{\"year\":\"VietGAP\",\"event\":\"\\u1ee8ng d\\u1ee5ng m\\u00f4 h\\u00ecnh tr\\u1ed3ng n\\u00f4ng s\\u1ea3n an to\\u00e0n VietGAP t\\u1ea1i di s\\u1ea3n C\\u1ed5 Loa.\"},{\"year\":\"OCOP C\\u1ea5p TP\",\"event\":\"\\u0110\\u1ea1t ch\\u1ee9ng nh\\u1eadn OCOP C\\u1ea5p Th\\u00e0nh ph\\u1ed1 H\\u00e0 N\\u1ed9i.\"}]'),
