INSERT INTO `wellness_services` (`id`, `eatery_id`, `name`, `price`, `description`, `image_path`, `duration`, `created_at`, `updated_at`) VALUES
(1, 51, 'Khám bệnh tổng quát', 150000.00, 'Khám sức khỏe tổng quát định kỳ bởi các bác sĩ chuyên khoa giàu kinh nghiệm.', 'https://images.unsplash.com/photo-1579684389782-64d84b5e901a?auto=format&fit=crop&w=800&q=80', '30 - 45 phút', '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
(2, 51, 'Khám bệnh theo yêu cầu', 300000.00, 'Khám tự nguyện chất lượng cao, ưu tiên quy trình nhanh gọn, bác sĩ Trưởng khoa/Phó khoa trực tiếp khám.', 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=800&q=80', '30 phút', '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
(3, 51, 'Chụp cắt lớp vi tính (CT Scanner)', 1200000.00, 'Chẩn đoán hình ảnh kỹ thuật cao bằng máy chụp đa dãy thế hệ mới, kết quả chính xác nhanh chóng.', 'https://images.unsplash.com/photo-1516062423079-7ca13cdc7f5a?auto=format&fit=crop&w=800&q=80', '20 phút', '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
(4, 52, 'Tiêm chủng vắc xin trọn gói', 500000.00, 'Gói tiêm chủng đầy đủ vắc xin phòng bệnh cho trẻ em và người lớn, vắc xin bảo quản chuẩn GSP.', 'https://images.unsplash.com/photo-1605647540924-852290f6b0d5?auto=format&fit=crop&w=800&q=80', '15 phút', '2026-07-27 15:03:31', '2026-07-27 15:03:31'),
(5, 52, 'Khám sức khỏe định kỳ / Học lái xe / Đi làm', 180000.00, 'Xét nghiệm và khám lâm sàng cấp giấy chứng nhận sức khỏe nhanh chóng, chuẩn quy định Bộ Y tế.', 'https://images.unsplash.com/photo-1505751172876-fa1923c5c528?auto=format&fit=crop&w=800&q=80', '60 phút', '2026-07-27 15:03:31', '2026-07-27 15:03:31');
